const WASEET_CITY = new Map(WASEET.map((c) => [c.id, { name: c.name, regions: new Map(c.regions) }]));

function parseFees(s) {
  // "بغداد:5000,البصرة:7000"
  const out = {};
  for (const part of s.split(/[,،;]/)) {
    const [k, v] = part.split(':').map((x) => (x || '').trim());
    if (k && v && !Number.isNaN(Number(v))) out[k] = Number(v);
  }
  return out;
}

const hyperpayEnabled = () =>
  Boolean(CFG.hyperpay.entityId && CFG.hyperpay.token && CFG.publicUrl);

// ------------------------------------------------------------ persistence ---

fs.mkdirSync(CFG.dataDir, { recursive: true });
const STORE_FILE = path.join(CFG.dataDir, 'state.json');

const state = (() => {
  try {
    return JSON.parse(fs.readFileSync(STORE_FILE, 'utf8'));
  } catch {
    return { pending: {}, idempotency: {} };
  }
})();

let saveTimer = null;
function writeStateNow() {
  clearTimeout(saveTimer);
  saveTimer = null;
  try {
    const tmp = STORE_FILE + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify(state));
    fs.renameSync(tmp, STORE_FILE);
  } catch (e) {
    console.error('state write failed', e.message);
  }
}
// A restart (settings saved, Reboot, crash) never loses the last changes.
process.on('exit', () => {
  if (saveTimer) writeStateNow();
});
for (const sig of ['SIGTERM', 'SIGINT']) {
  process.on(sig, () => {
    if (saveTimer) writeStateNow();
    process.exit(0);
  });
}

/** Keep the state file small: forget what is old or beyond a cap. */
function pruneState() {
  const now = Date.now();
  const cap = (obj, max) => {
    if (!obj) return;
    const keys = Object.keys(obj);
    for (const k of keys.slice(0, Math.max(0, keys.length - max))) delete obj[k]; // oldest first (insertion order)
  };
  const olderThan = (obj, ms, at = (v) => v) => {
    if (!obj) return;
    for (const [k, v] of Object.entries(obj)) if (now - Number(at(v) || 0) > ms) delete obj[k];
  };
  olderThan(state.discountDevices, 400 * 86400e3);
  cap(state.discountDevices, 50000);
  cap(state.discountUses, 100000);
  cap(state.devicePhones, 30000);
  cap(state.refDevices, 50000);
  cap(state.tierPhones, 100000);
  olderThan(state.checkouts, 3 * 86400e3, (v) => v.at);
  if (state.waseetLog) olderThan(state.waseetLog, 90 * 86400e3, (v) => Date.parse(v[v.length - 1]?.at || 0));
  if (state.abandonOffers) olderThan(state.abandonOffers, Math.max(60, CFG.abandon.everyDays * 2) * 86400e3);
  if (state.appCodes) olderThan(state.appCodes, 7 * 86400e3, (v) => v.exp);
  if (state.crashes) state.crashes = state.crashes.slice(0, 100);
  try {
    pruneAqsatiDocs();
  } catch (e) {
    log('docs prune', e.message);
  }
}

// Written at most every STATE_SAVE_MS. The timer is not pushed back by new
// changes: under a steady stream of requests a sliding timer would never fire
// and nothing would reach the disk until things calm down.
const STATE_SAVE_MS = Number(env('STATE_SAVE_MS', '500'));
function saveState() {
  if (saveTimer) return;
  saveTimer = setTimeout(() => {
    const now = Date.now();
    for (const [k, v] of Object.entries(state.idempotency)) {
      if (now - v.at > 24 * 3600e3) delete state.idempotency[k];
    }
    for (const [k, v] of Object.entries(state.pending)) {
      if (now - v.at > 3 * 24 * 3600e3) delete state.pending[k];
    }
    writeStateNow();
  }, STATE_SAVE_MS);
}

// --------------------------------------------------------- shopify admin ---

let tokenCache = { token: CFG.staticToken || null, exp: CFG.staticToken ? Infinity : 0 };

let tokenInFlight = null;
/** One token request at a time (background jobs may ask together). */
function adminToken() {
  if (tokenCache.token && Date.now() < tokenCache.exp) return Promise.resolve(tokenCache.token);
  tokenInFlight ??= fetchAdminToken().finally(() => (tokenInFlight = null));
  return tokenInFlight;
}

async function fetchAdminToken() {
  if (!CFG.clientId || !CFG.clientSecret) {
    throw new AppError(500, 'إعدادات Shopify غير مكتملة على الخادم');
  }
  const base = CFG.adminBase || `https://${CFG.shop}`;
  const res = await fetch(`${base}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'client_credentials',
      client_id: CFG.clientId,
      client_secret: CFG.clientSecret,
    }),
  });
  const json = await res.json().catch(() => ({}));
  if (!res.ok || !json.access_token) {
    log('token error', res.status, json);
    throw new AppError(502, 'تعذّر الاتصال بإدارة المتجر');
  }
  const ttl = Number(json.expires_in || 86399) * 1000;
  tokenCache = { token: json.access_token, exp: Date.now() + ttl - 5 * 60e3 };
  return tokenCache.token;
}

// ---- Shopify Admin gateway --------------------------------------------
// One door to the Admin API for everything the server does. It:
//  * spends Shopify's points budget (Grow plan: 100 points/s per app) with a
//    priority: orders > customer screens > background jobs. Background jobs
//    only run while plenty is left, so a rush of customers never waits behind
//    a poller;
//  * caps the total wait of a customer request (20 s) instead of 4 x 25 s;
//  * never blindly repeats a write: if a mutation's answer is lost the caller
//    is told (err.uncertain) and checks Shopify before trying again;
//  * shares identical reads that are in flight and keeps short-lived copies
//    when the caller asks for it (opts.cache).
const SHOP_GATE = {
  max: Number(env('SHOPIFY_BUCKET_MAX', '1000')),     // updated from Shopify's answers
  restore: Number(env('SHOPIFY_RESTORE_RATE', '100')), // points per second (Grow = 100)
  avail: null, at: 0, // last known
  inFlight: 0, maxInFlight: Number(env('SHOPIFY_MAX_INFLIGHT', '32')),
  queue: [], // waiting {prio, cost, resolve, deadline}
  est: new Map(), // operation -> last requested cost
  stats: { calls: 0, throttled: 0, waitedMs: 0, cacheHits: 0, coalesced: 0, uncertain: 0 },
};
const PRIO = { order: 0, ui: 1, low: 2, bg: 3 };
// Keep this share of the bucket free for higher priorities.
const RESERVE = { order: 0, ui: 0.1, low: 0.3, bg: 0.5 };
function gatePoints(now = Date.now()) {
  const g = SHOP_GATE;
  if (g.avail == null) return g.max;
  return Math.min(g.max, g.avail + ((now - g.at) / 1000) * g.restore);
}
function gateFits(prio, cost) {
  const g = SHOP_GATE;
  if (g.inFlight >= g.maxInFlight) return false;
  return gatePoints() - cost >= g.max * RESERVE[prio];
}
function gatePump() {
  const g = SHOP_GATE;
  g.queue.sort((a, b) => PRIO[a.prio] - PRIO[b.prio] || a.t - b.t);
  const now = Date.now();
  // Give up on every waiter past its deadline first (also the ones behind a
  // blocked higher-priority call), so nobody hangs past their budget.
  for (let i = 0; i < g.queue.length; i++) {
    const w = g.queue[i];
    if (now > w.deadline) { g.queue.splice(i--, 1); w.resolve(false); }
  }
  for (let i = 0; i < g.queue.length; i++) {
    const w = g.queue[i];
    if (!gateFits(w.prio, w.cost)) {
      // A higher-priority waiter that doesn't fit blocks the ones behind it,
      // otherwise cheap background calls would starve an order.
      if (w.prio === 'order' || w.prio === 'ui') break;
      continue;
    }
    g.queue.splice(i--, 1);
    gateTake(w.cost);
    w.resolve(true);
  }
  if (g.queue.length && !g.timer) {
    g.timer = setTimeout(() => { g.timer = null; gatePump(); }, 100);
    g.timer.unref?.();
  }
}
function gateTake(cost) {
  const g = SHOP_GATE;
  g.avail = gatePoints() - cost; // optimistic; corrected by Shopify's answer
  g.at = Date.now();
  g.inFlight++;
}
function gateRelease(throttleStatus, cost = 0) {
  const g = SHOP_GATE;
  g.inFlight = Math.max(0, g.inFlight - 1);
  if (!throttleStatus && cost && g.avail != null) {
    // No cost report (network error, older proxy): give the guess back.
    g.avail = Math.min(g.max, gatePoints() + cost);
    g.at = Date.now();
  }
  if (throttleStatus) {
    g.max = Number(throttleStatus.maximumAvailable) || g.max;
    g.restore = Number(throttleStatus.restoreRate) || g.restore;
    g.avail = Number(throttleStatus.currentlyAvailable);
    g.at = Date.now();
  }
  gatePump();
}
/** How long a new call of this priority would wait for Shopify points now. */
function gateWaitMs(prio, cost) {
  const g = SHOP_GATE;
  let ahead = cost;
  for (const w of g.queue) if (PRIO[w.prio] <= PRIO[prio]) ahead += w.cost;
  const free = gatePoints() - g.max * RESERVE[prio];
  return (Math.max(0, ahead - free) / g.restore) * 1000;
}
async function gateEnter(prio, cost, deadline) {
  const g = SHOP_GATE;
  if (!g.queue.length && gateFits(prio, cost)) { gateTake(cost); return true; }
  // Load shedding: if the points already queued ahead of this call cannot be
  // restored before its deadline, say "busy" now instead of after a long wait.
  // Under a rush this keeps the accepted requests fast instead of every
  // request waiting 20 s and then failing.
  if (Date.now() + gateWaitMs(prio, cost) > deadline) { g.stats.shed = (g.stats.shed || 0) + 1; return false; }
  const t = Date.now();
  const ok = await new Promise((resolve) => {
    SHOP_GATE.queue.push({ prio, cost, resolve, deadline, t });
    gatePump();
  });
  SHOP_GATE.stats.waitedMs += Date.now() - t;
  return ok;
}

// Short copies of read-only screens (prices for the cart badge, add-on quotes).
const READ_CACHE_MS = Number(env('READ_CACHE_MS', '30000'));
const adminCache = new Map(); // key -> {at, ttl, value} | {p}
function adminCachePut(key, v) {
  adminCache.delete(key);
  adminCache.set(key, v);
  if (adminCache.size > Number(env('ADMIN_CACHE_MAX', '20000'))) adminCache.delete(adminCache.keys().next().value);
}
function adminCacheDrop(prefix) {
  for (const k of adminCache.keys()) if (k.startsWith(prefix)) adminCache.delete(k);
}
setInterval(() => {
  const now = Date.now();
  for (const [k, v] of adminCache) if (v.at && now - v.at > Math.max(v.ttl, v.stale || 0)) adminCache.delete(k);
}, 60e3).unref();

const opName = (q) => (/^\s*(?:query|mutation)\s+(\w+)/.exec(q) || [])[1] || 'anon';

async function admin(query, variables = {}, opts = {}) {
  const key = opts.cache ? opts.cache.key : null;
  if (key) {
    const hit = adminCache.get(key);
    if (hit?.at && Date.now() - hit.at < hit.ttl) { SHOP_GATE.stats.cacheHits++; return hit.value; }
    if (hit?.p) { SHOP_GATE.stats.coalesced++; return hit.p; }
    const stale = hit?.at ? hit : null;
    const p = adminCall(query, variables, opts);
    adminCache.set(key, { p, stale });
    try {
      const value = await p;
      adminCachePut(key, { at: Date.now(), ttl: opts.cache.ttl, stale: opts.cache.staleMs || 0, value });
      return value;
    } catch (e) {
      // Shop too busy to answer in time: an earlier copy beats an error screen.
      if (e.status === 503 && stale && Date.now() - stale.at < (stale.stale || 0)) {
        adminCache.set(key, stale);
        SHOP_GATE.stats.servedStale = (SHOP_GATE.stats.servedStale || 0) + 1;
        return stale.value;
      }
      adminCache.delete(key);
      throw e;
    }
  }
  return adminCall(query, variables, opts);
}

async function adminCall(query, variables, opts) {
  const base = CFG.adminBase || `https://${CFG.shop}`;
  const mutation = /^\s*mutation\b/.test(query);
  const ctx = reqContext.getStore();
  const prio = opts.prio || ctx?.prio || (ctx ? 'ui' : 'bg');
  const budget = opts.budgetMs || ctx?.budgetMs || (prio === 'bg' ? 120e3 : prio === 'order' ? 25000 : Number(env('SHOPIFY_UI_BUDGET_MS', '15000')));
  const deadline = Date.now() + budget;
  const op = opName(query);
  const busy = () => new AppError(503, 'المتجر مشغول حالياً، حاول بعد لحظات');
  for (let attempt = 0; attempt < 6; attempt++) {
    const cost = SHOP_GATE.est.get(op) || (mutation ? 10 : 20);
    if (!(await gateEnter(prio, cost, deadline))) throw busy();
    const left = deadline - Date.now();
    if (left < 500) { gateRelease(null, cost); throw busy(); }
    SHOP_GATE.stats.calls++;
    let res;
    let json = null;
    try {
      res = await fetch(`${base}/admin/api/${CFG.apiVersion}/graphql.json`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Shopify-Access-Token': await adminToken(),
        },
        body: JSON.stringify({ query, variables }),
        signal: AbortSignal.timeout(Math.min(left, 15000)),
      });
      if (res.status < 500) json = await res.json().catch(() => ({}));
    } catch (e) {
      gateRelease(null, cost);
      log('admin fetch failed', op, attempt + 1, String(e.message || e).slice(0, 120));
      if (mutation && !opts.retrySafe) {
        // The write may or may not have happened. Never repeat it here.
        SHOP_GATE.stats.uncertain++;
        const err = busy();
        err.uncertain = true;
        throw err;
      }
      await sleep(Math.min(600 * (attempt + 1), Math.max(0, deadline - Date.now() - 500)));
      continue;
    }
    const cost0 = json?.extensions?.cost;
    if (cost0?.requestedQueryCost) SHOP_GATE.est.set(op, Number(cost0.requestedQueryCost));
    gateRelease(cost0?.throttleStatus, cost);
    if (res.status >= 500) {
      if (mutation && !opts.retrySafe) {
        SHOP_GATE.stats.uncertain++;
        const err = busy();
        err.uncertain = true;
        throw err;
      }
      await sleep(Math.min(800 * (attempt + 1), Math.max(0, deadline - Date.now() - 500)));
      continue;
    }
    if (res.status === 401 && !CFG.staticToken) {
      tokenCache = { token: null, exp: 0 };
      continue;
    }
    const throttled = (json.errors || []).some((e) => e?.extensions?.code === 'THROTTLED');
    if (throttled || res.status === 429) {
      // Shopify did not run the query: safe to retry, mutations included.
      SHOP_GATE.stats.throttled++;
      if (!cost0?.throttleStatus) { SHOP_GATE.avail = 0; SHOP_GATE.at = Date.now(); }
      continue; // the gate waits until enough points are back
    }
    if (!res.ok || json.errors) {
      log('admin error', res.status, JSON.stringify(json.errors || json).slice(0, 800));
      const err = new AppError(502, 'خطأ من إدارة المتجر، حاول مرة أخرى');
      err.shopify = (json.errors || []).map((e) => ({
        message: String(e?.message || ''),
        code: e?.extensions?.code || '',
        path: (e?.path || []).join('.'),
      }));
      if (!err.shopify.length) err.shopify = [{ message: `HTTP ${res.status}`, code: '', path: '' }];
      throw err;
    }
    if (mutation && opts.dropCache) for (const p of [].concat(opts.dropCache)) adminCacheDrop(p);
    return json.data;
  }
  throw busy();
}

const VARIANTS_QUERY = `
query Variants($ids: [ID!]!) {
  shop { currencyCode }
  nodes(ids: $ids) {
    ... on ProductVariant {
      id title sku price availableForSale
      product { id title status productType tags }
    }
  }
}`;

const ORDER_BY_SOURCE = `
query OrderBySource($q: String!) {
  orders(first: 1, query: $q) {
    nodes { id name customer { id } totalPriceSet { shopMoney { amount currencyCode } } }
  }
}`;
/** The order made from this checkout (sourceIdentifier = idempotency key), if
 *  Shopify has it. Search can lag a few seconds, so look three times. */
const uncertainOrders = new Map(); // idempotency key -> when its answer was lost
setInterval(() => { for (const [k, t] of uncertainOrders) if (Date.now() - t > 86400e3) uncertainOrders.delete(k); }, 3600e3).unref();
async function findOrderBySource(key) {
  for (const wait of [1500, 3000, 4500]) {
    await sleep(wait);
    try {
      const d = await admin(ORDER_BY_SOURCE, { q: `source_identifier:'${key}'` }, { prio: 'order', budgetMs: 15000 });
      const o = d.orders?.nodes?.[0];
      if (o) return o;
    } catch (e) {
      log('findOrderBySource', String(e.message || e).slice(0, 120));
    }
  }
  return null;
}

const ORDER_CREATE = `
mutation OrderCreate($order: OrderCreateOrderInput!, $options: OrderCreateOptionsInput) {
  orderCreate(order: $order, options: $options) {
    order { id name customer { id } totalPriceSet { shopMoney { amount currencyCode } } }
    userErrors { field message }
  }
}`;

// ------------------------------------------------------------- add-ons ---
// Cover / screen-protector services offered with phones and tablets.
// Prices are decided here, never by the app.

const ADDON_TYPES = env('ADDON_PRODUCT_TYPES', 'هواتف ذكية,هواتف,موبايلات,تابلت,أجهزة لوحية,ايباد,آيباد')
  .split(',').map((x) => x.trim()).filter(Boolean);

// [title pattern | min price, cover, protector] — first match wins.
const ADDON_RULES = [
  { match: /(1[78])\s*pro\s*max|(1[78])\s*برو\s*ماكس/i, cover: 10000, protector: 10000 },
  { match: /s\s*26\s*ultra|s\s*26\s*(ألترا|الترا)/i, cover: 10000, protector: 10000 },
  { min: 600000, cover: 5000, protector: 5000 },
  { min: 150000, cover: 4000, protector: 3000 },
];

function addonPrices(item) {
  if (!ADDON_TYPES.includes(String(item.productType || '').trim())) return null;
  for (const r of ADDON_RULES) {
    if (r.match ? r.match.test(item.title) : item.price >= r.min) {
      return { cover: r.cover, protector: r.protector };
    }
  }
  return null;
}

const ADDON_QUERY = `
query Addons { products(first: 50, query: "tag:'JiFire Cart Addon'") {
  nodes { handle title status variants(first: 1) { nodes { id price } } } } }`;
let addonCache = { at: 0, map: null };

/** {cover: {price: {variantId, title}}, protector: {...}} from Shopify service products. */
async function addonProducts() {
  if (addonCache.map && Date.now() - addonCache.at < 10 * 60e3) return addonCache.map;
  const map = { cover: {}, protector: {} };
  try {
    const data = await admin(ADDON_QUERY);
    for (const p of data.products.nodes) {
      if (p.status !== 'ACTIVE') continue;
      const v = p.variants.nodes[0];
      if (!v) continue;
      const kind = /protector|لاصق/i.test(p.handle + p.title) ? 'protector' : /case|كفر/i.test(p.handle + p.title) ? 'cover' : null;
      if (!kind) continue;
      const price = Math.round(Number(v.price));
      if (!map[kind][price]) map[kind][price] = { variantId: v.id, title: p.title };
    }
  } catch (e) {
    log('addon products lookup failed', e.message);
  }
  addonCache = { at: Date.now(), map };
  return map;
}

const ADDON_TITLE = {
  cover: (p) => `خدمة كفر حماية - ${p} دينار`,
  protector: (p) => `خدمة لاصق شاشة مع التركيب - ${p} دينار`,
};

/** Which add-ons each cart line can have, with prices. */
async function handleAddonQuote(body) {
  const lines = (Array.isArray(body?.lines) ? body.lines : [])
    .filter((l) => /^gid:\/\/shopify\/ProductVariant\/\d+$/.test(String(l?.variantId)))
    .slice(0, 30)
    .map((l) => ({ variantId: l.variantId, quantity: 1 }));
  if (!lines.length) return { lines: [] };
  const ids = [...new Set(lines.map((l) => l.variantId))];
  const data = await admin(VARIANTS_QUERY, { ids }, { cache: { key: 'var:' + [...ids].sort().join(','), ttl: READ_CACHE_MS, staleMs: 10 * 60e3 } });
  return {
    lines: (data.nodes || []).filter(Boolean).map((v) => {
      const prices = addonPrices({ title: v.product?.title || '', price: Number(v.price), productType: v.product?.productType });
      return { variantId: v.id, ...(prices ? { cover: prices.cover, protector: prices.protector } : {}) };
    }),
  };
}

/** Re-prices the cart from Shopify. Never trusts prices sent by the app. */
async function priceCart(lines) {
  const ids = [...new Set(lines.map((l) => l.variantId))];
  const data = await admin(VARIANTS_QUERY, { ids });
  const currency = data.shop.currencyCode;
  const byId = new Map((data.nodes || []).filter(Boolean).map((n) => [n.id, n]));
  const items = [];
  for (const l of lines) {
    const v = byId.get(l.variantId);
    if (!v || v.product?.status !== 'ACTIVE') {
      throw new AppError(409, 'أحد المنتجات في السلة لم يعد متوفراً، حدّث السلة وحاول مرة أخرى');
    }
    if (!v.availableForSale) {
      throw new AppError(409, `نفدت الكمية من: ${v.product.title}`);
    }
    items.push({
      variantId: v.id,
      quantity: l.quantity,
      title: v.product.title,
      variantTitle: v.title === 'Default Title' ? '' : v.title,
      productId: v.product.id,
      price: Number(v.price),
      productType: v.product.productType,
      addons: l.addons,
      cardOnly: isCardOnly(v.product.tags),
      codOnly: isCodOnly(v.product.tags),
      preorder: isPreorder(v.product.tags),
    });
  }
  // Cover / protector services chosen for phones and tablets.
  const services = [];
  if (items.some((i) => i.addons && (i.addons.cover || i.addons.protector))) {
    const products = await addonProducts();
    for (const i of items) {
      if (!i.addons) continue;
      const prices = addonPrices(i);
      if (!prices) continue;
      for (const kind of ['cover', 'protector']) {
        if (!i.addons[kind]) continue;
        const price = prices[kind];
        const sp = products[kind][price];
        const props = [{ name: 'للجهاز', value: i.title + (i.variantTitle ? ` (${i.variantTitle})` : '') }];
        if (kind === 'cover' && i.addons.note) props.push({ name: 'ملاحظة الكفر', value: i.addons.note });
        services.push({
          variantId: sp?.variantId || null,
          title: sp?.title || ADDON_TITLE[kind](price),
          quantity: i.quantity,
          price,
          service: kind,
          properties: props,
        });
      }
    }
  }
  items.push(...services);
  const subtotal = items.reduce((s, i) => s + i.price * i.quantity, 0);
  return { items, subtotal, currency };
}

function deliveryFee(order, subtotal) {
  if (order.delivery === 'pickup') return 0;
  if (CFG.tiers.enabled && CFG.tiers.vipFreeDelivery && tierOfPhone(order.customer?.phone) === 'vip') return 0;
  if (CFG.freeDeliveryOver > 0 && subtotal >= CFG.freeDeliveryOver) return 0;
  const g = order.address?.governorate;
  return CFG.deliveryFees[g] ?? CFG.defaultDeliveryFee;
}


// ------------------------------------------------------- discount codes ---
// Shopify discount codes, checked and calculated here (never by the app).

const DISCOUNT_QUERY = `
query DiscountByCode($code: String!) {
  codeDiscountNodeByCode(code: $code) {
    id
    codeDiscount {
      __typename
      ... on DiscountCodeBasic {
        title status usageLimit asyncUsageCount appliesOncePerCustomer
        context { __typename }
        minimumRequirement {
          __typename
          ... on DiscountMinimumSubtotal { greaterThanOrEqualToSubtotal { amount } }
          ... on DiscountMinimumQuantity { greaterThanOrEqualToQuantity }
        }
        customerGets {
          value {
            __typename
            ... on DiscountPercentage { percentage }
            ... on DiscountAmount { amount { amount } appliesOnEachItem }
          }
          items {
            __typename
            ... on DiscountProducts {
              products(first: 250) { nodes { id } }
              productVariants(first: 250) { nodes { id } }
            }
            ... on DiscountCollections { collections(first: 50) { nodes { id } } }
          }
        }
      }
      ... on DiscountCodeFreeShipping {
        title status usageLimit asyncUsageCount appliesOncePerCustomer
        context { __typename }
        maximumShippingPrice { amount }
        minimumRequirement {
          __typename
          ... on DiscountMinimumSubtotal { greaterThanOrEqualToSubtotal { amount } }
          ... on DiscountMinimumQuantity { greaterThanOrEqualToQuantity }
        }
      }
    }
  }
}`;

const PRODUCT_COLLECTIONS_QUERY = `
query DiscountCollections($ids: [ID!]!) {
  nodes(ids: $ids) {
    ... on ProductVariant { id product { id collections(first: 50) { nodes { id } } } }
  }
}`;

function cleanCode(c) {
  return String(c || '').trim().replace(/\s+/g, '').slice(0, 40);
}

/**
 * Checks `code` against the priced cart and returns
 * { code, title, amount, freeShipping } or throws an AppError in Arabic.
 * Service lines (cover / protector) are not discounted.
 */
async function evaluateDiscount(code, priced, order) {
  code = cleanCode(code);
  if (!code) return null;
  const own = state.appCodes?.[code.toUpperCase()];
  if (own) return evaluateAppCode(code.toUpperCase(), own, priced, order);
  let data;
  try {
    data = await admin(DISCOUNT_QUERY, { code });
  } catch (e) {
    if (e.shopify) {
      log('discount lookup denied', JSON.stringify(e.shopify).slice(0, 300));
      throw new AppError(503, 'أكواد الخصم غير مفعّلة بعد في المتجر (صلاحية read_discounts)');
    }
    throw e;
  }
  const d = data.codeDiscountNodeByCode?.codeDiscount;
  if (!d) throw new AppError(400, 'كود الخصم غير صحيح');
  if (d.__typename !== 'DiscountCodeBasic' && d.__typename !== 'DiscountCodeFreeShipping') {
    throw new AppError(400, 'هذا النوع من الخصم غير متاح في التطبيق، استخدمه من الموقع');
  }
  if (d.status !== 'ACTIVE') throw new AppError(400, 'كود الخصم منتهي أو غير مفعّل');
  if (d.usageLimit != null && d.asyncUsageCount >= d.usageLimit) {
    throw new AppError(400, 'انتهى عدد مرات استخدام هذا الكود');
  }
  const ctx = d.context?.__typename;
  if (ctx && ctx !== 'DiscountBuyerSelectionAll' && ctx !== 'DiscountMarkets') {
    throw new AppError(400, 'هذا الكود مخصص لعملاء محددين');
  }
  const phone = order?.customer?.phone;
  if (d.appliesOncePerCustomer && phone && state.discountUses?.[`${code.toLowerCase()}|${phone}`]) {
    throw new AppError(400, 'استخدمت هذا الكود من قبل');
  }
  // Same phone, another number/account: still once.
  const dev = order?._device || currentDevice();
  if (d.appliesOncePerCustomer && dev && state.discountDevices?.[`${code.toLowerCase()}|${dev}`]) {
    throw new AppError(400, 'هذا الكود مستخدم مسبقاً على هذا الجهاز');
  }

  const goods = priced.items.filter((i) => !i.service);
  const goodsTotal = goods.reduce((s, i) => s + i.price * i.quantity, 0);
  const goodsQty = goods.reduce((s, i) => s + i.quantity, 0);

  let eligible = goods;
  const items = d.customerGets?.items;
  if (items?.__typename === 'DiscountProducts') {
    const pids = new Set(items.products.nodes.map((n) => n.id));
    const vids = new Set(items.productVariants.nodes.map((n) => n.id));
    eligible = goods.filter((i) => vids.has(i.variantId) || pids.has(i.productId));
  } else if (items?.__typename === 'DiscountCollections') {
    const cids = new Set(items.collections.nodes.map((n) => n.id));
    const res = await admin(PRODUCT_COLLECTIONS_QUERY, { ids: [...new Set(goods.map((i) => i.variantId))] });
    const inColl = new Set(
      (res.nodes || []).filter(Boolean)
        .filter((n) => (n.product?.collections?.nodes || []).some((c) => cids.has(c.id)))
        .map((n) => n.id)
    );
    eligible = goods.filter((i) => inColl.has(i.variantId));
  }
  const eligibleTotal = eligible.reduce((s, i) => s + i.price * i.quantity, 0);
  const eligibleQty = eligible.reduce((s, i) => s + i.quantity, 0);

  const min = d.minimumRequirement;
  if (min?.__typename === 'DiscountMinimumSubtotal') {
    const need = Number(min.greaterThanOrEqualToSubtotal.amount);
    const base = items?.__typename && items.__typename !== 'AllDiscountItems' ? eligibleTotal : goodsTotal;
    if (base < need) {
      throw new AppError(400, `هذا الكود يتطلب مشتريات بقيمة ${need.toLocaleString('en-US')} دينار على الأقل`);
    }
  } else if (min?.__typename === 'DiscountMinimumQuantity') {
    const need = Number(min.greaterThanOrEqualToQuantity);
    const base = items?.__typename && items.__typename !== 'AllDiscountItems' ? eligibleQty : goodsQty;
    if (base < need) throw new AppError(400, `هذا الكود يتطلب ${need} قطع على الأقل`);
  }

  if (d.__typename === 'DiscountCodeFreeShipping') {
    if (order?.delivery === 'pickup') throw new AppError(400, 'هذا الكود للتوصيل المجاني فقط');
    const max = d.maximumShippingPrice ? Number(d.maximumShippingPrice.amount) : null;
    const fee = order ? deliveryFee(order, priced.subtotal) : 0;
    if (max != null && fee > max) throw new AppError(400, 'التوصيل لهذه المحافظة غير مشمول بهذا الكود');
    return { code, title: d.title, amount: 0, freeShipping: true };
  }

  if (!eligible.length) throw new AppError(400, 'الكود لا يشمل المنتجات الموجودة في سلتك');
  const v = d.customerGets.value;
  let amount = 0;
  if (v.__typename === 'DiscountPercentage') {
    amount = eligibleTotal * Number(v.percentage);
  } else if (v.__typename === 'DiscountAmount') {
    const a = Number(v.amount.amount);
    amount = v.appliesOnEachItem ? a * eligibleQty : a;
  } else {
    throw new AppError(400, 'هذا النوع من الخصم غير متاح في التطبيق');
  }
  amount = Math.round(Math.min(amount, eligibleTotal));
  if (amount <= 0) throw new AppError(400, 'الكود لا يشمل المنتجات الموجودة في سلتك');
  return { code, title: d.title, amount, freeShipping: false };
}

/** Personal "كمّل طلبك" code: one phone, one use, time-limited. */
function evaluateAppCode(code, c, priced, order) {
  const phone = order?.customer?.phone;
  if (!phone) throw new AppError(400, 'سجّل الدخول حتى تستخدم هذا الكود');
  if (c.phone !== phone) throw new AppError(400, 'هذا الكود مخصص لحساب آخر');
  if (c.used) throw new AppError(400, 'استخدمت هذا الكود من قبل');
  if (Date.now() > c.exp) throw new AppError(400, 'انتهت صلاحية هذا الكود');
  const goodsTotal = priced.items.filter((i) => !i.service).reduce((s, i) => s + i.price * i.quantity, 0);
  if (goodsTotal < c.min) {
    throw new AppError(400, `هذا الكود يتطلب مشتريات بقيمة ${c.min.toLocaleString('en-US')} دينار على الأقل`);
  }
  const amount = Math.round(Math.min(c.amount, goodsTotal));
  return { code, title: 'خصم إكمال الطلب', amount, freeShipping: false, appCode: true };
}

/** Delivery fee, discount and grand total for a priced order. */
function orderTotals(order, priced) {
  const disc = priced.discount;
  const fee = disc?.freeShipping ? 0 : deliveryFee(order, priced.subtotal);
  const discount = disc?.amount || 0;
  return { fee, discount, total: priced.subtotal - discount + fee };
}

/** Prices the cart and applies the order's discount code, if any. */
// --------------------------------------------- حجز مسبق / بطاقة فقط ---
// Shopify product tag «حجز مسبق» (or preorder) or «بطاقة فقط» (card-only):
// the order can only be paid by card (HyperPay); no cash on delivery, no
// installments, no points.
const isPreorder = (tags) => (tags || []).some((t) => /حجز|pre-?order/i.test(t));
const isCardOnly = (tags) => isPreorder(tags) || (tags || []).some((t) => /بطاقة فقط|card-?only/i.test(t));
// Tag «استلام فقط» / «دفع عند الاستلام فقط» / cod-only: cash on delivery only.
const isCodOnly = (tags) => (tags || []).some((t) => /استلام فقط|cod-?only/i.test(t));
function checkPaymentAllowed(order, priced) {
  const card = priced.items.filter((i) => i.cardOnly);
  const cod = priced.items.filter((i) => i.codOnly);
  if (card.length && cod.length) {
    throw new AppError(400, `«${card[0].title}» بالبطاقة فقط و«${cod[0].title}» عند الاستلام فقط، اطلبهم بطلبين منفصلين`);
  }
  if (card.length && order.payment && order.payment !== 'card') {
    throw new AppError(400, `«${card[0].title}» ${card[0].preorder ? 'حجز مسبق، ' : ''}الدفع له بالبطاقة فقط`);
  }
  if (cod.length && order.payment && order.payment !== 'cod') {
    throw new AppError(400, `«${cod[0].title}» الدفع له عند الاستلام فقط`);
  }
}

/** Checkout asks which payment methods this cart allows. */
async function handleCartRules(body) {
  const lines = Array.isArray(body?.lines) ? body.lines.slice(0, 50) : [];
  const ids = [...new Set(lines.map((l) => String(l?.variantId || '')).filter((x) => /^gid:\/\/shopify\/ProductVariant\/\d+$/.test(x)))];
  if (!ids.length) return { cardOnly: false, codOnly: false, products: [], codProducts: [] };
  const data = await admin(VARIANTS_QUERY, { ids }, { cache: { key: 'var:' + [...ids].sort().join(','), ttl: READ_CACHE_MS, staleMs: 10 * 60e3 } });
  const only = (data.nodes || []).filter((v) => v && isCardOnly(v.product?.tags));
  const cod = (data.nodes || []).filter((v) => v && isCodOnly(v.product?.tags));
  return {
    cardOnly: only.length > 0,
    codOnly: cod.length > 0,
    conflict: only.length > 0 && cod.length > 0,
    preorder: only.some((v) => isPreorder(v.product.tags)),
    products: [...new Set(only.map((v) => v.product.title))],
    codProducts: [...new Set(cod.map((v) => v.product.title))],
    cardEnabled: hyperpayEnabled(),
  };
}

async function priceOrder(order) {
  const priced = await priceCart(order.lines);
  checkPaymentAllowed(order, priced);
  if (order.discountCode) priced.discount = await evaluateDiscount(order.discountCode, priced, order);
  return priced;
}

async function handleDiscountCheck(body, sessionPhone) {
  const code = cleanCode(body?.code);
  if (!code) throw new AppError(400, 'اكتب كود الخصم');
  const lines = Array.isArray(body?.lines) ? body.lines : [];
  const order = validateOrder({
    lines,
    customer: { name: 'زبون التطبيق', phone: sessionPhone || '07700000000' },
    delivery: body?.delivery === 'pickup' ? 'pickup' : 'shipping',
    address: body?.address,
    payment: 'cod',
    idempotencyKey: 'discount-check-000000',
  }, { skipAddress: true, skipPayment: true });
  if (!sessionPhone) order.customer.phone = null;
  const priced = await priceCart(order.lines);
  const d = await evaluateDiscount(code, priced, order);
  return { code: d.code, title: d.title, amount: d.amount, freeShipping: d.freeShipping };
}

// --------------------------------------------------------- app banners ---
// Managed in Shopify admin: Content → Metaobjects → "بنرات التطبيق".

const BANNERS_QUERY = `
query Banners {
  metaobjects(type: "app_banner", first: 30) {
    nodes {
      id
      capabilities { publishable { status } }
      fields {
        key value
        reference {
          __typename
          ... on MediaImage { image { url width height } }
          ... on Collection { handle title }
          ... on Product { handle title }
        }
      }
    }
  }
}`;
let bannersCache = { at: 0, data: null };

// One Shopify call at a time for shared screens: when the copy expires during
// a rush, the first request fetches and the others wait for that answer.
const flights = new Map();
function singleFlight(key, fn) {
  if (!flights.has(key)) flights.set(key, Promise.resolve().then(fn).finally(() => flights.delete(key)));
  return flights.get(key);
}
function handleBanners() {
  if (bannersCache.data && Date.now() - bannersCache.at < 60e3) return Promise.resolve(bannersCache.data);
  return singleFlight('banners', loadBanners);
}
async function loadBanners() {
  if (bannersCache.data && Date.now() - bannersCache.at < 60e3) return bannersCache.data;
  let nodes = [];
  try {
    nodes = (await admin(BANNERS_QUERY, {})).metaobjects?.nodes || [];
  } catch (e) {
    log('banners failed', String(e.message || e).slice(0, 300));
    if (bannersCache.data) return bannersCache.data;
    return { banners: [] };
  }
  const now = Date.now();
  const banners = [];
  for (const n of nodes) {
    if (n.capabilities?.publishable?.status && n.capabilities.publishable.status !== 'ACTIVE') continue;
    const f = Object.fromEntries(n.fields.map((x) => [x.key, x]));
    const img = f.image?.reference?.image;
    if (!img?.url) continue;
    const t = (k) => (f[k]?.value ? Date.parse(f[k].value) : NaN);
    if (t('starts_at') > now || t('ends_at') < now) continue;
    let link = null;
    if (f.product?.reference?.handle) link = { type: 'product', handle: f.product.reference.handle, title: f.product.reference.title };
    else if (f.collection?.reference?.handle) link = { type: 'collection', handle: f.collection.reference.handle, title: f.collection.reference.title };
    else if (/^https?:\/\//.test(f.url?.value || '')) link = { type: 'url', url: f.url.value };
    banners.push({
      id: n.id,
      title: f.title?.value || '',
      image: img.url,
      aspect: img.width && img.height ? img.width / img.height : 2,
      link,
      sort: Number(f.sort?.value || 0),
    });
  }
  banners.sort((a, b) => a.sort - b.sort);
  bannersCache = { at: Date.now(), data: { banners } };
  return bannersCache.data;
}


// ------------------------------------------------------ shopping assistant ---
// Answers from the store's own catalog. Products come from the Storefront API
