// ---------------------------------------------------------- my orders ---
// "طلباتي" / order tracking in the app: the logged-in phone's Shopify orders
// with a 4-step status (received → preparing → on the way → delivered).

const MY_ORDERS_QUERY = `
query MyOrders($q: String!) {
  orders(first: 20, query: $q, sortKey: CREATED_AT, reverse: true) {
    nodes {
      id name createdAt cancelledAt tags displayFulfillmentStatus displayFinancialStatus
      totalPriceSet { shopMoney { amount } }
      currentSubtotalPriceSet { shopMoney { amount } }
      customAttributes { key value }
      customer { id }
      shippingAddress { city address1 }
      lineItems(first: 6) { nodes { title quantity image { url } product { id handle } variant { id } } }
      fulfillments(first: 3) { createdAt deliveredAt inTransitAt }
    }
  }
}`;

// Al-Waseet status: the delivery system tags the order "waseet: <status>"
// (Arabic text from Al-Waseet) every time the shipment moves.
const WASEET_MAP = [
  // [pattern, kind, step, tone, note for the customer, push?]
  [/تم التسليم (?:الى|إلى|ل)?\s*(?:ال)?زبون|تسليم للزبون|تم التسليم بنجاح|واصل/, 'delivered', 4, 'ok', 'تم تسليم طلبك بنجاح ✅', false],
  [/تم الارجاع|تم الإرجاع|ارجاع الى التاجر|إرجاع إلى التاجر|قيد الارجاع|قيد الإرجاع|مرتجع|راجع/, 'returned', 0, 'bad', 'طلبك راجع للمتجر. إذا تريده، تواصل ويانا ونرجع نرسله', true],
  [/ملغي|ملغى|الغاء|إلغاء|رفض/, 'cancelled', 0, 'bad', 'شركة التوصيل سجّلت الطلب كملغي. إذا ما طلبت الإلغاء، تواصل ويانا', false],
  [/معطل|غير فعال|غير معرف|غير داخل في الخدمة|لا يمكن الاتصال|مفصول/, 'badphone', 3, 'warn', 'المندوب ما گدر يتصل برقمك (معطل أو غير فعال). تواصل ويانا حتى نحدّث رقمك ويوصلك طلبك', true],
  [/العنوان|عنوان/, 'address', 3, 'warn', 'المندوب يحتاج يتأكد من عنوانك، وراح يتصل بيك. خلي جوالك قريب منك', true],
  [/لم يطلب|طلب مكرر|مستلم مسبق|حظر/, 'refused', 3, 'bad', 'شركة التوصيل سجّلت ملاحظة على طلبك. إذا تريد الطلب تواصل ويانا', true],
  [/مؤجل|تأجيل|تاجيل/, 'postponed', 3, 'warn', 'تأجل توصيل طلبك لليوم الثاني، ونعتذر عن التأخير', true],
  [/مغلق|خارج (?:نطاق )?الخدمة/, 'closed', 3, 'warn', 'حاول المندوب يتصل بيك وجوالك مغلق. خلي جوالك متاح حتى يوصلك طلبك', true],
  [/لا يرد|لايرد|عدم الرد|لا يجيب/, 'noanswer', 3, 'warn', 'حاول المندوب يتصل بيك وما رديت. خلي جوالك قريب منك', true],
  [/تبليغ|ابلاغ|إبلاغ/, 'notice', 3, 'warn', 'شركة التوصيل سجّلت ملاحظة على طلبك، وراح يتواصل وياك المندوب', true],
  [/عهدة المندوب|قيد التوصيل|مع المندوب|(?:الى|إلى) الزبون/, 'out', 3, 'ok', 'طلبك عند مندوب التوصيل وراح يوصلك قريباً. خلي جوالك قريب منك', true],
  [/فرز|مخزن|في الطريق/, 'transit', 3, 'ok', 'طلبك بالطريق لمحافظتك 🚛', true],
  [/مكتب المحافظة|في مكتب/, 'office', 3, 'ok', 'وصل طلبك لمكتب التوصيل بمحافظتك', true],
  [/استلام|المندوب/, 'picked', 3, 'ok', 'طلبك خرج للتوصيل، وسلّمناه لشركة الشحن 🚚', false], // the "shipped" push already says it
  [/فعال|جديد|قيد المعالجة/, 'active', 2, 'ok', 'تم تجهيز طلبك، وراح يستلمه مندوب شركة الشحن قريباً 📦', false],
];
function waseetClassify(text) {
  for (const [re, kind, step, tone, msg, push] of WASEET_MAP) if (re.test(text)) return { text, kind, step, tone, msg, push };
  return { text, kind: 'other', step: 3, tone: 'ok', msg: '', push: true };
}
function waseetInfo(tagList) {
  const tag = [...(tagList || [])].reverse().find((t) => /^waseet\s*:/i.test(String(t)));
  if (!tag) return null;
  const w = waseetClassify(String(tag).replace(/^waseet\s*:\s*/i, '').trim());
  if (!w.msg) w.msg = `حالة التوصيل: ${w.text}`;
  return w;
}
// Al-Waseet keeps one tag at a time, so the history is recorded here as the
// statuses arrive: the app shows the same sequence as the Al-Waseet panel.
function noteWaseet(orderId, w, at) {
  if (!w || !orderId) return;
  state.waseetLog = state.waseetLog || {};
  const log = (state.waseetLog[orderId] = state.waseetLog[orderId] || []);
  if (log.length && log[log.length - 1].t === w.text) return;
  log.push({ t: w.text, at: at || new Date().toISOString() });
  if (log.length > 30) log.splice(0, log.length - 30);
  saveState();
}
function waseetTimeline(orderId) {
  return ((state.waseetLog || {})[orderId] || []).map((e) => {
    const c = waseetClassify(e.t);
    return { status: e.t, note: c.kind === 'other' ? '' : c.msg, tone: c.tone, kind: c.kind, at: e.at };
  });
}

// Store status tags set by hand in Shopify ("osp: خرج للتوصيل"...). Several
// may be ticked at once: the most advanced one counts.
const OSP_MAP = [
  [/تم التسليم|تسليم الطلب|واصل/, 'delivered', 7],
  [/الغاء|إلغاء|ملغي|ملغى|ألغ/, 'cancelled', 0],
  [/راجع|مرتجع|ارجاع|إرجاع/, 'returned', 0],
  [/مؤجل|تأجيل|تاجيل/, 'postponed', -1],
  [/عند المندوب|قيد التوصيل|عهدة/, 'out', 6],
  [/مكتب المحافظة|مكتب/, 'office', 5],
  [/في الطريق|بالطريق/, 'transit', 4],
  [/خرج للتوصيل|شركة الشحن|تم الشحن|شحن/, 'picked', 3],
  [/تجهيز|جاهز/, 'prepared', 2],
  [/استلام الطلب|تأكيد|مؤكد/, 'received', 1],
];
function ospInfo(tagList) {
  const texts = (tagList || []).filter((t) => /^osp\s*:/i.test(String(t))).map((t) => String(t).replace(/^osp\s*:\s*/i, '').trim());
  let best = null;
  let hold = null;
  for (const text of texts) {
    const m = OSP_MAP.find(([re]) => re.test(text));
    if (!m) continue; // payment notes etc.
    const [, kind, stage] = m;
    if (kind === 'postponed') { hold = { kind, text }; continue; }
    const rank = kind === 'delivered' ? 9 : stage === 0 ? 8 : stage;
    if (!best || rank > best.rank) best = { kind, stage, text, rank };
  }
  if (!best && !hold) return null;
  return { ...(best || { kind: 'postponed', stage: 0, text: hold.text }), hold };
}

function orderStep(o) {
  const w = waseetInfo(o.tags);
  const osp0 = ospInfo(o.tags);
  if (w && !o.cancelledAt && !(osp0 && ['delivered', 'cancelled', 'returned'].includes(osp0.kind))) {
    if (w.kind === 'delivered') return { step: 4, status: 'delivered', at: null, waseet: w };
    if (w.kind === 'returned') return { step: 0, status: 'returned', at: null, waseet: w };
    if (w.kind === 'cancelled') return { step: 0, status: 'cancelled', at: null, waseet: w };
    const step = Math.max(w.step, osp0 && osp0.stage >= 3 ? 3 : 0);
    return { step, status: step === 2 ? 'preparing' : 'shipped', at: null, waseet: w, osp: osp0 };
  }
  const osp = osp0;
  const f = o.fulfillments || [];
  if (o.cancelledAt) return { step: 0, status: 'cancelled' };
  if (osp?.kind === 'delivered') return { step: 4, status: 'delivered', at: f.find((x) => x.deliveredAt)?.deliveredAt || null, osp };
  if (osp?.kind === 'cancelled') return { step: 0, status: 'cancelled', osp };
  if (osp?.kind === 'returned') return { step: 0, status: 'returned', osp };
  if (osp && osp.stage >= 3) return { step: 3, status: 'shipped', at: f[0]?.createdAt || null, osp };
  if (osp?.stage === 2) return { step: 2, status: 'preparing', osp };
  // Without a store status tag, plain tags still count (older manual workflow).
  const tags = osp ? '' : (o.tags || []).filter((t) => !/^waseet\s*:/i.test(String(t))).join(' ');
  if (/إلغاء|ملغي|cancel/i.test(tags)) return { step: 0, status: 'cancelled' };
  const delivered = f.find((x) => x.deliveredAt);
  if (delivered || /تم التوصيل|تم التسليم|واصل|delivered/i.test(tags)) {
    return { step: 4, status: 'delivered', at: delivered?.deliveredAt || null };
  }
  // Sent to Al-Waseet but no driver yet: fulfilling the order only uploads it to
  // the delivery company, so it stays "preparing" until Al-Waseet moves it
  // (24h safety net in case no status ever arrives).
  const viaWaseet = (o.customAttributes || []).some((a) => a.key === '_alwaseet_region_id' && a.value);
  const fulfilledAt = Date.parse(f[0]?.createdAt || '') || 0;
  if (viaWaseet && fulfilledAt && Date.now() - fulfilledAt < 24 * 3600e3) {
    return {
      step: 2,
      status: 'preparing',
      waseet: { kind: 'handed', text: '', push: false, msg: 'تم تجهيز طلبك، وراح يستلمه مندوب شركة الشحن قريباً 📦' },
    };
  }
  if (['FULFILLED', 'PARTIALLY_FULFILLED', 'IN_PROGRESS'].includes(o.displayFulfillmentStatus) || /خرج للتوصيل|بالطريق|shipped/i.test(tags)) {
    return { step: 3, status: 'shipped', at: f[0]?.inTransitAt || f[0]?.createdAt || null };
  }
  if (/تجهيز|تم التأكيد|مؤكد|confirmed|preparing/i.test(tags)) return { step: 2, status: 'preparing' };
  return { step: 1, status: 'received' };
}

// Detailed stages shown in the app (same sequence as Al-Waseet):
// 1 تم الاستلام → 2 تم التجهيز → 3 سُلّم لشركة الشحن → 4 بالطريق لمكتب المحافظة
// → 5 في مكتب المحافظة → 6 قيد التوصيل (في عهدة المندوب) → 7 تم التسليم.
// 0 = cancelled / returned. Postponed, closed phone… keep the stage reached
// and are reported as `hold`. Pickup orders use 1 → 2 → 7.
const STAGE_OF_KIND = { active: 2, handed: 2, picked: 3, transit: 4, office: 5, out: 6, delivered: 7 };
const HOLD_KINDS = new Set(['postponed', 'closed', 'noanswer', 'notice', 'badphone', 'address', 'refused', 'other']);
const HOLD_LABEL = { postponed: 'مؤجل', closed: 'الجوال مغلق', noanswer: 'لا يرد', notice: 'تبليغ', badphone: 'الرقم معطل', address: 'تأكيد العنوان', refused: 'ملاحظة' };
function orderStage(o, st) {
  st = st || orderStep(o);
  const pickup = (o.tags || []).some((t) => String(t).includes('استلام من المتجر'));
  const times = Array(8).fill(null);
  times[1] = o.createdAt || null;
  const f = (o.fulfillments || [])[0];
  if (f?.createdAt) times[2] = f.createdAt;
  const log = o.id ? waseetTimeline(o.id) : [];
  let reached = 0;
  for (const e of log) {
    const s = STAGE_OF_KIND[e.kind];
    if (!s) continue;
    reached = Math.max(reached, s);
    if (!times[s]) times[s] = e.at;
  }
  if (st.step === 0) return { stage: 0, pickup, times, hold: null };
  const w = st.waseet;
  let stage;
  let hold = null;
  if (st.step === 4) stage = 7;
  else if (w && STAGE_OF_KIND[w.kind]) stage = STAGE_OF_KIND[w.kind];
  else if (w && HOLD_KINDS.has(w.kind)) {
    stage = Math.max(reached, 6);
    hold = { kind: w.kind, text: w.text, label: HOLD_LABEL[w.kind] || w.text };
  } else if (st.step === 3) stage = pickup ? 7 : 3;
  else if (st.step === 2) stage = 2;
  else stage = 1;
  if (st.osp && stage < 7) {
    if (st.osp.stage > 0) stage = Math.max(stage, st.osp.stage);
    if (st.osp.hold && !hold) hold = { kind: 'postponed', text: st.osp.hold.text, label: 'مؤجل' };
  }
  stage = Math.max(stage, Math.min(reached, 6));
  if (pickup && stage > 2 && stage < 7) stage = 2;
  if (stage === 7 && !times[7]) times[7] = f?.deliveredAt || st.at || null;
  // earlier stages that were skipped (e.g. Baghdad has no governorate office)
  return { stage, pickup, times, hold };
}

async function handleMyOrders(phone) {
  const c = await customerByPhone(phone);
  if (!c) return { orders: [] };
  const id = c.id.split('/').pop();
  const data = await myOrders(id);
  return {
    orders: (data.orders?.nodes || []).map((o) => {
      const st = orderStep(o);
      if (st.waseet?.text) noteWaseet(o.id, st.waseet);
      return {
        id: o.id,
        name: o.name,
        createdAt: o.createdAt,
        total: Number(o.totalPriceSet?.shopMoney?.amount || 0),
        city: o.shippingAddress?.city || '',
        address: o.shippingAddress?.address1 || '',
        step: st.step,
        status: st.status,
        statusAt: st.at || null,
        ...(() => { const g = orderStage(o, st); return { stage: g.stage, pickup: g.pickup, stageTimes: g.times, hold: g.hold }; })(),
        delivery: st.waseet?.msg || '',
        deliveryLog: waseetTimeline(o.id),
        canCancel: canCustomerCancel(o),
        cancelUntil: new Date(Date.parse(o.createdAt) + cancelWindowMs()).toISOString(),
        items: (o.lineItems?.nodes || []).map((li) => ({ title: li.title, quantity: li.quantity, image: li.image?.url || null, handle: li.product?.handle || null, variantId: li.variant?.id || null })),
      };
    }),
  };
}

// ------------------------------------------- إلغاء الطلب من الزبون ---
// Within CANCEL_MINUTES (default 10) of placing it, if nothing was prepared or
// shipped and nothing was paid online (card/installments go through support).
const CANCEL_ORDER_QUERY = `
query CancelCheck($id: ID!) {
  order(id: $id) {
    id name createdAt cancelledAt tags displayFulfillmentStatus displayFinancialStatus
    customer { id }
    fulfillments(first: 3) { createdAt deliveredAt inTransitAt }
  }
}`;

function cancelWindowMs() {
  return Math.max(0, num('CANCEL_MINUTES', 10)) * 60e3;
}

/** Can the customer still cancel this order (for the app's button). */
function canCustomerCancel(o) {
  if (!o || o.cancelledAt) return false;
  if (Date.now() - Date.parse(o.createdAt) > cancelWindowMs()) return false;
  if (o.displayFulfillmentStatus && o.displayFulfillmentStatus !== 'UNFULFILLED') return false;
  if (!['PENDING', 'AUTHORIZED', 'EXPIRED'].includes(o.displayFinancialStatus || 'PENDING')) return false;
  return orderStep(o).step <= 1;
}

async function customerCancelOrder(phone, body) {
  const id = String(body?.id || '');
  if (!/^gid:\/\/shopify\/Order\/\d+$/.test(id)) throw new AppError(400, 'طلب غير صحيح');
  const c = await customerByPhone(phone);
  const d = await admin(CANCEL_ORDER_QUERY, { id });
  const o = d.order;
  if (!o || !c || o.customer?.id !== c.id) throw new AppError(404, 'الطلب غير موجود');
  if (o.cancelledAt) throw new AppError(400, 'الطلب ملغي مسبقاً');
  if (!['PENDING', 'AUTHORIZED', 'EXPIRED'].includes(o.displayFinancialStatus || 'PENDING')) {
    throw new AppError(400, 'الطلبات المدفوعة بالبطاقة أو الأقساط تُلغى عبر التواصل معنا');
  }
  if (!canCustomerCancel(o)) {
    throw new AppError(400, `انتهت مدة الإلغاء (${Math.round(cancelWindowMs() / 60e3)} دقائق) أو بدأ تجهيز الطلب. تواصل معنا`);
  }
  const r = await admin(
    `mutation C($id: ID!, $note: String) {
      orderCancel(orderId: $id, reason: CUSTOMER, restock: true, notifyCustomer: false, staffNote: $note) {
        job { id }
        orderCancelUserErrors { message }
      }
    }`,
    { id, note: 'ألغاه الزبون من التطبيق' }
  );
  dropMyOrders(c.id);
  const errs = r.orderCancel?.orderCancelUserErrors || [];
  if (errs.length) {
    log('customer cancel failed', o.name, JSON.stringify(errs).slice(0, 300));
    throw new AppError(400, 'تعذّر إلغاء الطلب، تواصل معنا');
  }
  await admin(`mutation T($id: ID!, $tags: [String!]!) { tagsAdd(id: $id, tags: $tags) { userErrors { message } } }`, {
    id,
    tags: ['ألغاه الزبون من التطبيق'],
  }).catch(() => {});
  log('customer cancelled', o.name, phone.slice(-4));
  return { ok: true, name: o.name };
}

const PAYMENT_LABEL = {
  cod: 'الدفع عند الاستلام',
  card: 'بطاقة (HyperPay)',
  aqsati: 'أقساطي (كي كارد)',
};

// The order note carries the nearest landmark first (Al-Waseet reads the note),
// then whatever the customer wrote.
function orderNote(order, pickup) {
  const lm = !pickup ? order.address?.landmark : '';
  const parts = [lm ? `أقرب نقطة دالة: ${lm}` : '', order.note || ''].filter(Boolean);
  return parts.length ? parts.join(' — ') : null;
}

async function createShopifyOrder(order, priced, { paid, gatewayRef, review, aqsati }) {
  const { fee, discount, total } = orderTotals(order, priced);
  const disc = priced.discount;
  const money = (amount) => ({
    shopMoney: { amount: amount.toFixed(2), currencyCode: priced.currency },
  });
  const [firstName, ...rest] = order.customer.name.trim().split(/\s+/);
  const lastName = rest.join(' ') || firstName;
  const pickup = order.delivery === 'pickup';

  const address = pickup
    ? null
    : {
        firstName,
        lastName,
        phone: order.customer.phone,
        address1: order.address.area + (order.address.street ? ` - ${order.address.street}` : ''),
        address2: order.address.landmark || null,
        city: order.address.governorate,
        countryCode: 'IQ',
      };

  const gateway =
    order.payment === 'card'
      ? 'HyperPay'
      : order.payment === 'aqsati'
        ? CFG.aqsati.gateway
        : 'Cash on Delivery (COD)';

  const tags = [CFG.orderTag, PAYMENT_LABEL[order.payment], pickup ? 'استلام من المتجر' : 'توصيل'];
  // Priority support: the team sees the customer's level on the order.
  const lvl = TIERS.enabled ? tierOfPhone(order.customer.phone) : null;
  if (lvl === 'gold' || lvl === 'vip') tags.push(lvl === 'vip' ? 'زبون VIP' : 'زبون ذهبي');
  if (review) tags.push('دفع قيد المراجعة');

  const attrs = [
    { key: 'طريقة الدفع', value: PAYMENT_LABEL[order.payment] },
    { key: 'طريقة الاستلام', value: pickup ? 'استلام من المتجر' : 'توصيل' },
  ];
  if (!pickup && order.address?.cityId) {
    // Read by the existing system when it sends fulfilled orders to Al-Waseet.
    attrs.push(
      { key: 'talabati_city_id', value: String(order.address.cityId) },
      { key: 'talabati_region_id', value: String(order.address.regionId) },
      { key: 'الوسيط - المحافظة', value: `${order.address.governorate} (${order.address.cityId})` },
      { key: 'الوسيط - المنطقة', value: `${order.address.area} (${order.address.regionId})` },
      // Same keys as website (checkout) orders: the live Al-Waseet upload reads these.
      { key: 'المحافظة', value: order.address.governorate },
      { key: '_alwaseet_city_id', value: String(order.address.cityId) },
      { key: 'المنطقة', value: order.address.area },
      { key: '_alwaseet_region_id', value: String(order.address.regionId) },
      // The Al-Waseet upload reads the landmark from the English key "landmark" (Arabic value).
      ...(order.address.landmark
        ? [{ key: 'landmark', value: order.address.landmark }, { key: 'أقرب نقطة دالة', value: order.address.landmark }]
        : [])
    );
  }
  const consent = state.consent?.[order.customer.phone];
  if (consent) attrs.push({ key: 'موافقة عروض واتساب', value: consent.wa ? 'نعم' : 'لا' });
  if (disc?.points) {
    attrs.push(
      { key: 'jifire_points_redeemed', value: String(disc.points) },
      { key: 'نقاط الولاء المستبدلة', value: `${disc.points} نقطة (-${discount})` }
    );
    tags.push('استبدال نقاط ولاء');
  } else if (disc) {
    attrs.push({ key: 'كود الخصم', value: disc.code + (discount ? ` (-${discount})` : ' (توصيل مجاني)') });
    tags.push('كود خصم: ' + disc.code);
  }
  if (gatewayRef && order.payment === 'card') attrs.push({ key: 'مرجع HyperPay', value: gatewayRef });
  if (aqsati) {
    attrs.push(
      { key: 'رقم معاملة أقساطي', value: String(aqsati.installmentId ?? '') },
      { key: 'عدد الأشهر', value: String(aqsati.plan.months) },
      { key: 'المبلغ بعد الفائدة', value: String(aqsati.plan.finalAmount) },
      { key: 'القسط الشهري', value: String(aqsati.plan.perMonth) },
      { key: 'رقم حساب أقساطي', value: String(aqsati.identity) },
      ...(aqsati.docId ? [{ key: 'مستمسكات أقساطي', value: `${CFG.publicUrl}/admin/docs/${aqsati.docId}` }] : [])
    );
    if (aqsatiDemo()) tags.push('تجربة أقساطي – ليس حقيقياً');
    else tags.push('osp: تم الدفع عن طريق اقساطي بنجاح');
  }

  const input = {
    currency: priced.currency,
    lineItems: priced.items.map((i) => ({
      ...(i.variantId ? { variantId: i.variantId } : { title: i.title }),
      quantity: i.quantity,
      priceSet: money(i.price),
      // Without this Shopify marks app orders "Shipping not required".
      requiresShipping: !pickup,
      ...(i.properties ? { properties: i.properties } : {}),
    })),
    phone: order.customer.phone,
    email: order.customer.email || null,
    note: orderNote(order, pickup),
    tags,
    customAttributes: attrs,
    sourceName: 'jifire-app',
    sourceIdentifier: order.idempotencyKey,
    financialStatus: paid ? 'PAID' : 'PENDING',
    transactions: [
      {
        kind: 'SALE',
        status: paid ? 'SUCCESS' : 'PENDING',
        gateway,
        amountSet: money(total),
        ...(gatewayRef ? { authorizationCode: gatewayRef } : {}),
      },
    ],
    shippingLines: [
      {
        title: pickup ? CFG.pickup.title : 'توصيل',
        code: pickup ? 'pickup' : 'delivery',
        priceSet: money(fee),
      },
    ],
    ...(address ? { shippingAddress: address, billingAddress: address } : {}),
    ...(disc
      ? {
          discountCode: disc.freeShipping
            ? { freeShippingDiscountCode: { code: disc.code } }
            : { itemFixedDiscountCode: { code: disc.code, amountSet: money(discount) } },
        }
      : {}),
  };
  // Same phone = same customer: attach the order to the existing Shopify
  // customer instead of creating a duplicate (e.g. matched by email only).
  let existingId = null;
  if (CFG.upsertCustomer) {
    try {
      existingId =
        (await customerIdByPhone(order.customer.phone)) ||
        (await createCustomerForPhone(order.customer.phone, order.customer.name, order.customer.email));
    } catch (e) {
      log('customer lookup/create failed', String(e.message || e).slice(0, 200));
    }
  }
  if (existingId) {
    input.customer = { toAssociate: { id: existingId } };
    // An order email that belongs to ANOTHER customer makes Shopify move the
    // order to that customer (then it's missing from the buyer's «طلباتي»).
    // Keep the order on the phone's customer: the email stays in the notes.
    if (input.email) {
      const ownerEmail = (await customerByPhone(order.customer.phone).catch(() => null))?.defaultEmailAddress?.emailAddress || '';
      if (ownerEmail.toLowerCase() !== String(input.email).toLowerCase()) {
        input.customAttributes = [...(input.customAttributes || []), { key: 'البريد الإلكتروني', value: input.email }];
        input.email = ownerEmail || null;
      }
    }
  } else if (CFG.upsertCustomer) {
    // Lookup/create failed: upsert by phone only, and keep the email off the
    // order so Shopify can't attach it to whoever owns that email.
    if (input.email) {
      input.customAttributes = [...(input.customAttributes || []), { key: 'البريد الإلكتروني', value: input.email }];
      input.email = null;
    }
    input.customer = {
      toUpsert: {
        firstName,
        lastName,
        phone: order.customer.phone,
        ...(state.consent?.[order.customer.phone]?.wa ? { tags: [WA_TAG] } : {}),
      },
    };
  }

  const options = {
    inventoryBehaviour: 'DECREMENT_OBEYING_POLICY',
    sendReceipt: CFG.sendReceipt && Boolean(order.customer.email),
  };

  // Shopify may refuse protected customer fields (name/phone/address) or the
  // customer upsert depending on the app type and store plan. Try the full
  // order first, then progressively simpler versions so the order always
  // lands in admin with every detail visible.
  const contact = [
    ['الاسم', order.customer.name],
    ['الهاتف', order.customer.phone],
    ...(order.customer.email ? [['البريد', order.customer.email]] : []),
    ...(address
      ? [
          ['المحافظة', order.address.governorate],
          ['المنطقة', order.address.area],
          ...(order.address.street ? [['الشارع', order.address.street]] : []),
          ...(order.address.landmark ? [['أقرب نقطة دالة', order.address.landmark]] : []),
        ]
      : []),
  ];
  const withoutCustomer = () => {
    const c = { ...input };
    delete c.customer;
    return c;
  };
  const withoutProtected = () => {
    const c = withoutCustomer();
    delete c.shippingAddress;
    delete c.billingAddress;
    delete c.phone;
    delete c.email;
    c.customAttributes = [...attrs, ...contact.map(([key, value]) => ({ key, value }))];
    c.note = [contact.map(([k, v]) => `${k}: ${v}`).join('\n'), order.note].filter(Boolean).join('\n\n');
    c.tags = [...tags, 'بيانات الزبون في الملاحظات'];
    return c;
  };
  const attempts = [input, ...(input.customer ? [withoutCustomer()] : []), withoutProtected()];

  let data = null;
  let lastErr = null;
  // An earlier try of this checkout lost its answer: it may already exist.
  if (uncertainOrders.has(order.idempotencyKey)) {
    const found = await findOrderBySource(order.idempotencyKey);
    if (found) data = { orderCreate: { order: found, userErrors: [] } };
  }
  for (const attempt of data ? [] : attempts) {
    try {
      data = await admin(ORDER_CREATE, { order: attempt, options }, { prio: 'order', budgetMs: 25000 });
    } catch (e) {
      if (e.uncertain) {
        // The answer was lost: the order may exist. Look before writing again.
        const found = await findOrderBySource(order.idempotencyKey);
        if (found) { data = { orderCreate: { order: found, userErrors: [] } }; break; }
        log('orderCreate uncertain, not found; trying once more', order.idempotencyKey);
        try {
          data = await admin(ORDER_CREATE, { order: attempt, options }, { prio: 'order', budgetMs: 20000 });
        } catch (e2) {
          if (e2.uncertain) uncertainOrders.set(order.idempotencyKey, Date.now());
          throw e2;
        }
      } else if (!e.shopify) {
        throw e; // throttle/budget: nothing was written, the app may retry
      } else {
        lastErr = e;
        log('orderCreate attempt failed', JSON.stringify(e.shopify).slice(0, 600));
        data = null;
        continue;
      }
    }
    const errs = data.orderCreate.userErrors;
    if (!errs.length) break;
    log('orderCreate userErrors', JSON.stringify(errs));
    const msg = errs.map((e) => e.message).join('، ');
    if (/inventory|stock|available/i.test(msg)) {
      throw new AppError(422, 'الكمية المطلوبة غير متوفرة حالياً');
    }
    lastErr = new AppError(422, 'تعذّر إنشاء الطلب: ' + msg);
    data = null;
  }
  if (!data) {
    const detail = lastErr?.shopify
      ? lastErr.shopify.map((x) => `${x.code || ''} ${x.message}`.trim()).join(' | ').slice(0, 300)
      : '';
    throw new AppError(lastErr?.status || 502,
      (lastErr?.message || 'خطأ من إدارة المتجر') + (detail ? ` (${detail})` : ''));
  }
  const o = data.orderCreate.order;
  bumpCustomerOrders(order.customer.phone);
  dropMyOrders(o.customer?.id || existingId);
  if (consent) syncConsent(order.customer.phone, existingId || o.customer?.id || null);
  if (order.customer.phone && state.checkouts?.[order.customer.phone]) delete state.checkouts[order.customer.phone];
  if (disc?.appCode && state.appCodes?.[disc.code]) {
    state.appCodes[disc.code].used = Date.now();
    state.abandonStats = state.abandonStats || { sent: 0, used: 0 };
    state.abandonStats.used++;
  }
  if (disc && !disc.points) {
    state.discountUses = state.discountUses || {};
    state.discountUses[`${disc.code.toLowerCase()}|${order.customer.phone}`] = Date.now();
    const dev = order._device || currentDevice();
    if (dev) {
      state.discountDevices = state.discountDevices || {};
      state.discountDevices[`${disc.code.toLowerCase()}|${dev}`] = Date.now();
    }
    saveState();
  }
  return {
    orderId: o.id,
    orderName: o.name,
    customerId: existingId || o.customer?.id || null,
    total,
    discount,
    deliveryFee: fee,
    currency: priced.currency,
  };
}

function aqsatiUrl(order, created) {
  const t = CFG.aqsati.redirectUrl;
  if (!t) return null;
  const vals = {
    order_id: created.orderId.split('/').pop(),
    order_gid: created.orderId,
    order_name: created.orderName,
    order_number: created.orderName.replace(/^#/, ''),
    total: String(Math.round(created.total)),
    phone: order.customer.phone,
    name: order.customer.name,
    email: order.customer.email || '',
  };
  return t.replace(/\{(\w+)\}/g, (m, k) => (k in vals ? encodeURIComponent(vals[k]) : m));
}

// -------------------------------------------------------------- hyperpay ---

const HP_SUCCESS = /^(000\.000\.|000\.100\.1|000\.[36])/;
const HP_REVIEW = /^(000\.400\.0[^3]|000\.400\.100)/;
const HP_PENDING = /^(000\.200)/;

async function hyperpayPrepare(amount, ref, order) {
  const hp = CFG.hyperpay;
  const gatewayAmount = (amount * hp.rate).toFixed(2);
  const body = new URLSearchParams({
    entityId: hp.entityId,
    amount: gatewayAmount,
    currency: hp.currency,
    paymentType: 'DB',
    merchantTransactionId: ref,
    'customer.mobile': order.customer.phone,
    'customer.givenName': order.customer.name.split(/\s+/)[0],
    'customer.surname': order.customer.name.split(/\s+/).slice(1).join(' ') || '-',
    ...(order.customer.email ? { 'customer.email': order.customer.email } : {}),
    'billing.country': 'IQ',
    'billing.city': order.address?.governorate || 'Baghdad',
    'billing.street1': order.address?.area || 'Store pickup',
    ...(hp.testMode ? { testMode: hp.testMode } : {}),
  });
  const res = await fetch(`${hp.host}/v1/checkouts`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${hp.token}` },
    body,
  });
  const json = await res.json().catch(() => ({}));
  if (!json.id) {
    log('hyperpay prepare failed', res.status, JSON.stringify(json).slice(0, 500));
    throw new AppError(502, 'تعذّر بدء الدفع بالبطاقة، جرّب طريقة دفع أخرى');
  }
  return { checkoutId: json.id, integrity: json.integrity || null, gatewayAmount };
}

async function hyperpayStatus(checkoutId) {
  const hp = CFG.hyperpay;
  const url = `${hp.host}/v1/checkouts/${encodeURIComponent(checkoutId)}/payment?entityId=${encodeURIComponent(hp.entityId)}`;
  const res = await fetch(url, { headers: { Authorization: `Bearer ${hp.token}` } });
  return res.json().catch(() => ({}));
}

// ------------------------------------------------------------ otp login ---

const whatsappOtpEnabled = () => Boolean(CFG.otp.authkey && CFG.otp.waNumber && CFG.otp.waTemplate);
const otpEnabled = () =>
  Boolean((CFG.otp.authkey && CFG.otp.templateId) || whatsappOtpEnabled() || (CFG.otp.testPhone && CFG.otp.testCode));
const otpChannels = () => [
  ...(CFG.otp.authkey && CFG.otp.templateId ? ['sms'] : []),
  ...(whatsappOtpEnabled() ? ['whatsapp'] : []),
];

const SESSION_SECRET = (() => {
  const fromEnv = env('SESSION_SECRET');
  if (fromEnv) return fromEnv;
  const f = path.join(CFG.dataDir, 'session.key');
  try {
    return fs.readFileSync(f, 'utf8').trim();
  } catch {
    const k = crypto.randomBytes(32).toString('hex');
    fs.mkdirSync(CFG.dataDir, { recursive: true });
    fs.writeFileSync(f, k, { mode: 0o600 });
    return k;
  }
})();

function signSession(phone) {
  const body = Buffer.from(
    JSON.stringify({ p: phone, e: Date.now() + CFG.otp.sessionDays * 864e5 })
  ).toString('base64url');
  const sig = crypto.createHmac('sha256', SESSION_SECRET).update(body).digest('base64url');
  return `${body}.${sig}`;
}

function readSession(req) {
  const h = String(req.headers.authorization || '');
  const tok = h.startsWith('Bearer ') ? h.slice(7).trim() : '';
  const [body, sig] = tok.split('.');
  if (!body || !sig) return null;
  const want = crypto.createHmac('sha256', SESSION_SECRET).update(body).digest('base64url');
  const a = Buffer.from(sig);
  const b = Buffer.from(want);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return null;
  try {
    const s = JSON.parse(Buffer.from(body, 'base64url').toString('utf8'));
    const ok = s.e > Date.now() && typeof s.p === 'string' ? s.p : null;
    if (ok) rememberDevicePhone(ok);
    return ok;
  } catch {
    return null;
  }
}

/** +9647XXXXXXXXX -> 9647XXXXXXXXX (MSG91 format: country code, no +) */
const msg91Mobile = (phone) => phone.replace(/^\+/, '');

async function msg91(method, pathQs, body) {
  const res = await fetch(`${CFG.otp.host}${pathQs}`, {
    method,
    headers: { authkey: CFG.otp.authkey, accept: 'application/json', 'content-type': 'application/json' },
    ...(body ? { body: JSON.stringify(body) } : {}),
  });
  const json = await res.json().catch(() => ({}));
  return json;
}

const otpHash = (phone, code) => crypto.createHmac('sha256', SESSION_SECRET).update(`${phone}|${code}`).digest('hex');

/** Sends our own code through an approved MSG91 WhatsApp authentication template. */
async function sendWhatsappOtp(phone) {
  const code = String(crypto.randomInt(10 ** (CFG.otp.length - 1), 10 ** CFG.otp.length));
  const components = { body_1: { type: 'text', value: code } };
  if (CFG.otp.waButton) components.button_1 = { subtype: 'url', type: 'text', value: code };
  const r = await msg91('POST', '/api/v5/whatsapp/whatsapp-outbound-message/bulk/', {
    integrated_number: CFG.otp.waNumber,
    content_type: 'template',
    payload: {
      messaging_product: 'whatsapp',
      type: 'template',
      template: {
        name: CFG.otp.waTemplate,
        language: { code: CFG.otp.waLang, policy: 'deterministic' },
        ...(CFG.otp.waNamespace ? { namespace: CFG.otp.waNamespace } : {}),
        to_and_components: [{ to: [msg91Mobile(phone)], components }],
      },
    },
  });
  const ok = r && (r.status === 'success' || r.type === 'success' || r.hasError === false);
  if (!ok) {
    log('msg91 whatsapp send failed', JSON.stringify(r).slice(0, 300));
    throw new AppError(502, 'تعذّر إرسال الرمز عبر واتساب، جرّب الرسائل النصية');
  }
  state.waOtp = state.waOtp || {};
  state.waOtp[phone] = { h: otpHash(phone, code), exp: Date.now() + CFG.otp.expiryMin * 60e3 };
  saveState();
}

// ---- WhatsApp marketing consent -> Shopify customer
const CUSTOMER_BY_PHONE = `
query CustomerByPhone($q: String!) {
  customers(first: 20, query: $q) {
    nodes {
      id firstName lastName numberOfOrders
      defaultPhoneNumber { phoneNumber }
      defaultEmailAddress { emailAddress }
    }
  }
}`;

const CUSTOMER_BY_IDENTIFIER = `
query CustomerByIdentifier($phone: String!) {
  customerByIdentifier(identifier: { phoneNumber: $phone }) {
    id firstName lastName numberOfOrders
    defaultPhoneNumber { phoneNumber }
    defaultEmailAddress { emailAddress }
  }
}`;

/** The Shopify customer that owns exactly this phone. Exact lookup first
 *  (no search-index delay, so a customer made a minute ago is found and no
 *  duplicate is created); the fuzzy search is only a fallback. */
const customerCache = new Map(); // phone -> {at, c}  (a customer's id never changes)
const CUSTOMER_TTL = Number(env('CUSTOMER_CACHE_MS', String(24 * 3600e3)));
const customerLookups = new Map(); // phone -> in-flight lookup
function forgetCustomer(phone) {
  if (!phone) return;
  customerCache.delete(phone);
  // The disk copy stays, but only as a fallback for busy moments.
  const k = customerKnown.get(phone);
  if (k) k.at = Math.min(k.at, Date.now() - CUSTOMER_TTL);
}
/** One more order: keep the copy, just count it (no new lookup needed). */
function bumpCustomerOrders(phone) {
  const h = customerCache.get(phone);
  if (h?.c) h.c = { ...h.c, numberOfOrders: Number(h.c.numberOfOrders || 0) + 1 };
  const k = customerKnown.get(phone);
  if (k?.c) { k.c = { ...k.c, numberOfOrders: Number(k.c.numberOfOrders || 0) + 1 }; customerDirty = true; }
}
function rememberCustomer(phone, id) {
  if (phone && id && CUSTOMER_TTL > 0) {
    const c = { id, firstName: '', lastName: '', numberOfOrders: 0, defaultPhoneNumber: { phoneNumber: phone }, defaultEmailAddress: null };
    customerCache.set(phone, { at: Date.now(), c });
    knowCustomer(phone, c);
  }
}
// Customers already identified are also kept on disk (customers.json), so a
// restart or a rush of people not seen for a day doesn't ask Shopify for each
// of them again. When Shopify is too busy, the last known copy is used.
const CUSTOMER_FILE = path.join(CFG.dataDir, 'customers.json');
const customerKnown = new Map(); // phone -> {at, c}  (on disk, up to 60 days)
const CUSTOMER_KEEP = 60 * 86400e3;
let customerDirty = false;
try {
  if (CUSTOMER_TTL > 0) {
    for (const [ph, v] of Object.entries(JSON.parse(fs.readFileSync(CUSTOMER_FILE, 'utf8')))) {
      if (Date.now() - v[5] > CUSTOMER_KEEP) continue;
      customerKnown.set(ph, { at: v[5], c: { id: 'gid://shopify/Customer/' + v[0], firstName: v[1] || '', lastName: v[2] || '', numberOfOrders: v[4], defaultPhoneNumber: { phoneNumber: ph }, defaultEmailAddress: v[3] ? { emailAddress: v[3] } : null } });
    }
  }
} catch {}
function knowCustomer(phone, c) {
  if (!c?.id || CUSTOMER_TTL <= 0) return;
  customerKnown.delete(phone); // re-insert: newest last
  customerKnown.set(phone, { at: Date.now(), c });
  if (customerKnown.size > 300000) customerKnown.delete(customerKnown.keys().next().value);
  customerDirty = true;
}
function saveKnownCustomers() {
  if (!customerDirty) return;
  customerDirty = false;
  const out = {};
  for (const [ph, { at, c }] of customerKnown) {
    out[ph] = [c.id.split('/').pop(), c.firstName || '', c.lastName || '', c.defaultEmailAddress?.emailAddress || '', Number(c.numberOfOrders || 0), at];
  }
  try {
    fs.writeFileSync(CUSTOMER_FILE + '.tmp', JSON.stringify(out));
    fs.renameSync(CUSTOMER_FILE + '.tmp', CUSTOMER_FILE);
  } catch (e) {
    log('customers file', e.message);
  }
}
setInterval(saveKnownCustomers, 60e3).unref();
process.on('exit', saveKnownCustomers);
setInterval(() => { for (const [k, v] of customerCache) if (Date.now() - v.at > CUSTOMER_TTL) customerCache.delete(k); }, 5 * 60e3).unref();
async function customerByPhone(phone) {
  if (!phone) return null;
  const hit = customerCache.get(phone);
  if (hit && Date.now() - hit.at < CUSTOMER_TTL) { SHOP_GATE.stats.cacheHits++; return hit.c; }
  const known = customerKnown.get(phone);
  if (known && Date.now() - known.at < CUSTOMER_TTL) { SHOP_GATE.stats.cacheHits++; return known.c; }
  // Shared only between callers of the same priority: a quick "low" lookup
  // that gives up must not fail a customer screen that could have waited.
  const lk = phone + '|' + (reqContext.getStore()?.prio || 'bg');
  if (customerLookups.has(lk)) { SHOP_GATE.stats.coalesced++; return customerLookups.get(lk); }
  const p = customerByPhoneLive(phone).then((c) => {
    // Not found is kept only 20 s: a customer can appear any time (we drop it
    // ourselves when we create one).
    if (c || CUSTOMER_TTL > 0) customerCache.set(phone, { at: c ? Date.now() : Date.now() - CUSTOMER_TTL + 20e3, c });
    if (c) knowCustomer(phone, c);
    return c;
  }, (e) => {
    // Shopify busy: a customer's id never changes, the last known copy is fine.
    if (e?.status === 503 && known && Date.now() - known.at < CUSTOMER_KEEP) {
      SHOP_GATE.stats.servedStale = (SHOP_GATE.stats.servedStale || 0) + 1;
      return known.c;
    }
    throw e;
  }).finally(() => customerLookups.delete(lk));
  customerLookups.set(lk, p);
  return p;
}
async function customerByPhoneLive(phone) {
  try {
    const d = await admin(CUSTOMER_BY_IDENTIFIER, { phone });
    const c = d.customerByIdentifier;
    if (c && c.defaultPhoneNumber?.phoneNumber === phone) return c;
  } catch (e) {
    if (e.status === 503) throw e; // busy: the fuzzy search would cost 4x more
    log('customerByIdentifier', String(e.message || e).slice(0, 160));
  }
  const found = await admin(CUSTOMER_BY_PHONE, { q: `phone:${phone}` });
  const hits = (found.customers?.nodes || []).filter((n) => n.defaultPhoneNumber?.phoneNumber === phone);
  // Several with the same number (old duplicates): keep the one with most orders.
  hits.sort((a, b) => Number(b.numberOfOrders || 0) - Number(a.numberOfOrders || 0));
  return hits[0] || null;
}

async function customerIdByPhone(phone) {
  return (await customerByPhone(phone))?.id || null;
}

/** New phone: create its own customer (never merge into an email owner). */
async function createCustomerForPhone(phone, name, email) {
  forgetCustomer(phone);
  const [firstName, ...rest] = String(name || '').trim().split(/\s+/);
  const base = {
    phone,
    ...(firstName ? { firstName, lastName: rest.join(' ') || firstName } : {}),
    tags: ['تطبيق جي فاير', ...(state.consent?.[phone]?.wa ? [WA_TAG] : [])],
  };
  for (const input of email ? [{ ...base, email }, base] : [base]) {
    const r = await admin(CUSTOMER_CREATE, { input });
    const id = r.customerCreate?.customer?.id;
    if (id) {
      rememberCustomer(phone, id);
      spendCache.set(id, { at: Date.now(), v: { spent: 0, orders: 0 } }); // brand new: nothing spent yet
      return id;
    }
    log('customerCreate', JSON.stringify(r.customerCreate?.userErrors).slice(0, 300));
  }
  // "Phone has already been taken" (two requests at once): use that customer.
  return (await customerByPhone(phone).catch(() => null))?.id || null;
}
const CUSTOMER_CREATE = `
mutation CustomerCreate($input: CustomerInput!) {
  customerCreate(input: $input) { customer { id } userErrors { field message } }
}`;
const TAGS_ADD = `
mutation TagsAdd($id: ID!, $tags: [String!]!) { tagsAdd(id: $id, tags: $tags) { userErrors { message } } }`;
const TAGS_REMOVE = `
mutation TagsRemove($id: ID!, $tags: [String!]!) { tagsRemove(id: $id, tags: $tags) { userErrors { message } } }`;
const WA_CONSENT = `
mutation WaConsent($input: CustomerWhatsAppMarketingConsentUpdateInput!) {
  customerWhatsAppMarketingConsentUpdate(input: $input) { userErrors { field message } }
}`;
const WA_TAG = 'موافق عروض واتساب';
// The same tick also covers SMS offers (Shopify's official SMS consent field).
const SMS_CONSENT = `
mutation SmsConsent($input: CustomerSmsMarketingConsentUpdateInput!) {
  customerSmsMarketingConsentUpdate(input: $input) { userErrors { field message } }
}`;
const CUSTOMER_UPDATE = `
mutation CustomerUpdate($input: CustomerInput!) {
  customerUpdate(input: $input) { customer { id } userErrors { field message } }
}`;

/** "حسابي → تعديل بياناتي": update the Shopify customer that owns this phone. */
async function handleProfile(phone, body) {
  forgetCustomer(phone);
  const name = String(body?.name || '').trim().replace(/\s+/g, ' ').slice(0, 80);
  const email = String(body?.email || '').trim().slice(0, 120);
  if (name.length < 3) throw new AppError(400, 'اكتب اسمك الكامل');
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new AppError(400, 'البريد الإلكتروني غير صحيح');
  const [firstName, ...rest] = name.split(' ');
  const lastName = rest.join(' ') || firstName;
  let id = await customerIdByPhone(phone);
  if (!id) {
    let made = await admin(CUSTOMER_CREATE, {
      input: { phone, firstName, lastName, tags: ['تطبيق جي فاير'], ...(email ? { email } : {}) },
    });
    id = made.customerCreate?.customer?.id;
    let emailSaved = Boolean(email);
    if (!id && email) {
      // the email belongs to another customer: create with the phone only
      log('profile create (with email)', JSON.stringify(made.customerCreate?.userErrors).slice(0, 300));
      made = await admin(CUSTOMER_CREATE, { input: { phone, firstName, lastName, tags: ['تطبيق جي فاير'] } });
      id = made.customerCreate?.customer?.id;
      emailSaved = false;
    }
    if (!id) {
      log('profile create', JSON.stringify(made.customerCreate?.userErrors).slice(0, 300));
      throw new AppError(502, 'تعذّر حفظ البيانات في المتجر');
    }
    return { ok: true, emailSaved };
  }
  let r = await admin(CUSTOMER_UPDATE, { input: { id, firstName, lastName, ...(email ? { email } : {}) } });
  let errs = r.customerUpdate?.userErrors || [];
  let emailSaved = Boolean(email);
  if (errs.length && email) {
    // e.g. the email already belongs to another customer: keep the name at least.
    log('profile update (with email)', JSON.stringify(errs).slice(0, 300));
    r = await admin(CUSTOMER_UPDATE, { input: { id, firstName, lastName } });
    errs = r.customerUpdate?.userErrors || [];
    emailSaved = false;
  }
  if (errs.length) {
    log('profile update', JSON.stringify(errs).slice(0, 300));
    throw new AppError(502, 'تعذّر حفظ البيانات في المتجر');
  }
  return { ok: true, emailSaved };
}

function recordConsent(phone, agreed) {
  if (typeof agreed !== 'boolean') return;
  state.consent = state.consent || {};
  const prev = state.consent[phone];
  if (prev && prev.wa === agreed && prev.synced) return;
  state.consent[phone] = { wa: agreed, at: new Date().toISOString(), synced: null };
  saveState();
}

/** Pushes the saved consent to Shopify. Never throws (login/orders must not fail). */
async function syncConsent(phone, customerId = null) {
  forgetCustomer(phone);
  const c = state.consent?.[phone];
  if (!c || (c.synced && (!customerId || c.synced === customerId))) return;
  try {
    let id = customerId;
    if (!id) id = await customerIdByPhone(phone);
    if (!id && c.wa) {
      const made = await admin(CUSTOMER_CREATE, { input: { phone, tags: ['تطبيق جي فاير', WA_TAG] } });
      id = made.customerCreate?.customer?.id || null;
      if (!id) log('consent customerCreate', JSON.stringify(made.customerCreate?.userErrors).slice(0, 300));
    }
    if (!id) return; // no customer yet: synced with the first order
    await admin(c.wa ? TAGS_ADD : TAGS_REMOVE, { id, tags: [WA_TAG] });
    const r = await admin(WA_CONSENT, {
      input: {
        customerId: id,
        whatsAppMarketingConsent: {
          state: c.wa ? 'SUBSCRIBED' : 'UNSUBSCRIBED',
          optInLevel: 'SINGLE_OPT_IN',
          updatedAt: c.at,
        },
      },
    });
    const errs = r.customerWhatsAppMarketingConsentUpdate?.userErrors || [];
    if (errs.length) log('whatsapp consent userErrors', JSON.stringify(errs).slice(0, 300));
    if (bool('SMS_CONSENT_SYNC', true)) {
      const r2 = await admin(SMS_CONSENT, {
        input: {
          customerId: id,
          smsMarketingConsent: {
            marketingState: c.wa ? 'SUBSCRIBED' : 'UNSUBSCRIBED',
            marketingOptInLevel: 'SINGLE_OPT_IN',
            consentUpdatedAt: c.at,
          },
        },
      });
      const e2 = r2.customerSmsMarketingConsentUpdate?.userErrors || [];
      if (e2.length) log('sms consent userErrors', JSON.stringify(e2).slice(0, 300));
    }
    c.synced = id;
    saveState();
  } catch (e) {
    log('consent sync failed', String(e.message || e).slice(0, 300));
  }
}

async function handleOtpSend(body, ip) {
  if (!otpEnabled()) throw new AppError(400, 'تسجيل الدخول برمز التحقق غير مفعّل');
  const phone = normalizePhone(body?.phone);
  if (!phone) throw new AppError(400, 'رقم الهاتف غير صحيح، مثال: 07701234567');
  rateLimit(ip, 'otp-send-ip', Number(env('OTP_SENDS_PER_IP_10MIN', '10')), 10 * 60e3);
  rateLimit(phone, 'otp-send', 3, 10 * 60e3);
  if (CFG.otp.testPhone && normalizePhone(CFG.otp.testPhone) === phone) return { ok: true };

  const channels = otpChannels();
  const channel = body?.channel === 'whatsapp' ? 'whatsapp' : 'sms';
  if (!channels.includes(channel)) {
    throw new AppError(400, channel === 'whatsapp' ? 'الإرسال عبر واتساب غير متاح حالياً' : 'الرسائل النصية غير متاحة حالياً');
  }
  if (channel === 'whatsapp') {
    await sendWhatsappOtp(phone);
    return { ok: true, channel };
  }
  if (state.waOtp?.[phone]) {
    delete state.waOtp[phone];
    saveState();
  }

  const retry = body?.resend === true;
  const q = new URLSearchParams({ mobile: msg91Mobile(phone) });
  let r;
  if (retry) {
    q.set('retrytype', 'text');
    r = await msg91('GET', `/api/v5/otp/retry?${q}`);
  }
  if (!retry || r?.type !== 'success') {
    q.delete('retrytype');
    q.set('template_id', CFG.otp.templateId);
    q.set('otp_length', String(CFG.otp.length));
    q.set('otp_expiry', String(CFG.otp.expiryMin));
    r = await msg91('POST', `/api/v5/otp?${q}`);
  }
  if (r?.type !== 'success') {
    log('msg91 send failed', JSON.stringify(r).slice(0, 300));
    throw new AppError(502, 'تعذّر إرسال رمز التحقق، حاول بعد قليل');
  }
  return { ok: true };
}

async function handleOtpVerify(body, ip) {
  if (!otpEnabled()) throw new AppError(400, 'تسجيل الدخول برمز التحقق غير مفعّل');
  const phone = normalizePhone(body?.phone);
  const code = String(body?.code || '').replace(/[٠-٩]/g, (c) => '٠١٢٣٤٥٦٧٨٩'.indexOf(c)).replace(/\D/g, '');
  if (!phone || code.length < 4 || code.length > 8) throw new AppError(400, 'أدخل رمز التحقق');
  rateLimit(ip, 'otp-verify-ip', Number(env('OTP_SENDS_PER_IP_10MIN', '10')) * 2, 10 * 60e3);
  rateLimit(phone, 'otp-verify', 6, 10 * 60e3);

  let ok;
  if (CFG.otp.testPhone && normalizePhone(CFG.otp.testPhone) === phone) {
    ok = code === CFG.otp.testCode;
  } else if (state.waOtp?.[phone]) {
    const w = state.waOtp[phone];
    if (w.exp < Date.now()) {
      delete state.waOtp[phone];
      saveState();
      throw new AppError(400, 'انتهت صلاحية الرمز، اطلب رمزاً جديداً');
    }
    const a = Buffer.from(otpHash(phone, code));
    ok = crypto.timingSafeEqual(a, Buffer.from(w.h));
    if (ok) {
      delete state.waOtp[phone];
      saveState();
    }
  } else {
    const q = new URLSearchParams({ otp: code, mobile: msg91Mobile(phone) });
    const r = await msg91('GET', `/api/v5/otp/verify?${q}`);
    ok = r?.type === 'success';
    if (!ok) log('msg91 verify failed', JSON.stringify(r).slice(0, 200));
    if (!ok && /expired/i.test(String(r?.message))) {
      throw new AppError(400, 'انتهت صلاحية الرمز، اطلب رمزاً جديداً');
    }
  }
  if (!ok) throw new AppError(400, 'رمز التحقق غير صحيح');
  if (typeof body?.whatsappConsent === 'boolean') {
    recordConsent(phone, body.whatsappConsent);
    syncConsent(phone); // in the background
  }
  let profile = null;
  try {
    const c = await customerByPhone(phone);
    if (c) {
      profile = {
        name: [c.firstName, c.lastName].filter(Boolean).join(' ').trim(),
        email: c.defaultEmailAddress?.emailAddress || '',
        orders: Number(c.numberOfOrders || 0),
      };
    }
  } catch (e) {
    log('login profile lookup failed', String(e.message || e).slice(0, 200));
  }
  return { token: signSession(phone), phone, expiresInDays: CFG.otp.sessionDays, profile };
}

// --------------------------------------------------------------- aqsati ---
// Direct Aqsati (Qi Card) financing. Same API and plans as the existing
// Aqsati page, but the Shopify order is created only after the installment
// is approved.

const aqsatiDemo = () => CFG.aqsati.apiBase.toLowerCase() === 'demo';
const aqsatiEnabled = () =>
  CFG.aqsati.enabled && (aqsatiDemo() || Boolean(CFG.aqsati.apiBase && CFG.aqsati.merchantKey));

/** Demo mode (AQSATI_API_BASE_URL=demo): simulated Aqsati answers for trying the app. */
function aqsatiDemoAnswer(pathName, body) {
  if (pathName === '/GetCustomerInformation') {
    if (String(body.Identity) === '0000') throw new AppError(400, 'الحساب غير موجود (تجربة)');
    return {
      session: { sessionId: 'DEMO-' + crypto.randomBytes(4).toString('hex') },
      merchantInformation: { productInformation: { minCountOfMonth: 3, maxCountOfMonth: 24, repaymentLimit: 500000 } },
    };
  }
  if (pathName === '/ValidatorOfInstallment') return { message: 'ok' };
  if (pathName === '/CreateInstallment') {
    if (Number(body.OTP) !== 1234) throw new AppError(400, 'رمز التحقق غير صحيح (رمز التجربة 1234)');
    return { installmentId: 'DEMO' + Date.now().toString().slice(-6), operationId: 'DEMO' };
  }
  return {};
}

async function aqsatiPost(pathName, body) {
  if (aqsatiDemo()) return aqsatiDemoAnswer(pathName, body);
  let res;
  try {
    res = await fetch(`${CFG.aqsati.apiBase}${pathName}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: CFG.aqsati.merchantKey },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(30000),
    });
  } catch (e) {
    log('aqsati network', pathName, e.message);
    throw new AppError(502, 'تعذّر الاتصال بأقساطي، حاول بعد قليل');
  }
  const json = await res.json().catch(() => ({}));
  if (!res.ok) {
    log('aqsati http', pathName, res.status, JSON.stringify(json).slice(0, 300));
    throw new AppError(502, json?.message || `خطأ من أقساطي (${res.status})`);
  }
  if (!json.succeeded) {
    log('aqsati refused', pathName, JSON.stringify(json).slice(0, 300));
    throw new AppError(400, json?.message || 'رفضت أقساطي الطلب');
  }
  return json.data || {};
}

function aqsatiPending(ref, phone) {
  const p = state.pending[ref];
  if (!p || p.kind !== 'aqsati' || Date.now() - p.at > 30 * 60e3) {
    throw new AppError(410, 'انتهت مهلة عملية التقسيط، ابدأ من جديد');
  }
  if (otpEnabled() && p.order.customer.phone !== phone) throw new AppError(403, 'غير مصرّح');
  return p;
}

const planOptions = (amount, min, max) =>
  CFG.aqsati.plans
    .filter(([m]) => (!min || m >= min) && (!max || m <= max))
    .map(([months, rate]) => {
      const finalAmount = Math.round(amount * (1 + rate / 100));
      return { months, rate, finalAmount, perMonth: Math.round(finalAmount / months) };
    });

/** Step 1: validate cart + customer, price it, keep it pending. No order yet. */
async function aqsatiStart(body, ip, sessionPhone) {
  if (!aqsatiEnabled()) throw new AppError(400, 'أقساطي غير متاح حالياً');
  assertOrdersOpen();
  if (otpEnabled() && !sessionPhone) throw new AppError(401, 'سجّل الدخول برقم هاتفك أولاً');
  const order = validateOrder({ ...body, payment: 'aqsati' }, { allowAqsati: true });
  if (sessionPhone) order.customer.phone = sessionPhone;
  rateLimit(ip, 'aqsati-start', 10, 10 * 60e3);
  const priced = await priceOrder(order);
  await applyPointsDiscount(order, priced);
  const { fee, total: amount } = orderTotals(order, priced);
  const ref = 'AQ' + crypto.randomBytes(12).toString('base64url');
  state.pending[ref] = { kind: 'aqsati', at: Date.now(), order, priced, amount, stage: 'identity', tries: 0 };
  saveState();
  return { ref, amount, deliveryFee: fee, currency: priced.currency, plans: planOptions(amount) };
}

/** Step 2: Qi account number -> Aqsati session + allowed months. */
async function aqsatiIdentity(body, sessionPhone) {
  const p = aqsatiPending(String(body?.ref || ''), sessionPhone);
  const identity = String(body?.identity || '').replace(/[٠-٩]/g, (c) => '٠١٢٣٤٥٦٧٨٩'.indexOf(c)).replace(/\s+/g, '');
  if (!/^[A-Za-z0-9-]{4,40}$/.test(identity)) throw new AppError(400, 'أدخل رقم الحساب بشكل صحيح');
  if (++p.tries > 6) throw new AppError(429, 'محاولات كثيرة، ابدأ من جديد');
  const data = await aqsatiPost('/GetCustomerInformation', { Identity: identity });
  const info = data?.merchantInformation?.productInformation || {};
  const sessionId = data?.session?.sessionId;
  if (!sessionId) throw new AppError(502, 'ردّ غير متوقع من أقساطي');
  const plans = planOptions(p.amount, info.minCountOfMonth, info.maxCountOfMonth);
  if (!plans.length) throw new AppError(400, 'لا توجد خطة تقسيط مناسبة لحسابك');
  Object.assign(p, {
    stage: 'plan',
    identity,
    sessionId,
    repaymentLimit: info.repaymentLimit,
  });
  saveState();
  return {
    plans,
    repaymentLimit: info.repaymentLimit ?? null,
    docs: docsRequired() ? Object.entries(DOC_KINDS).map(([kind, label]) => ({ kind, label, done: Boolean(p.docs?.[kind]) })) : [],
  };
}

// ------------------------------------------------------ aqsati documents ---
// Before the Aqsati code, the customer photographs the national ID card and
// the residence card (front + back). Photos are encrypted (AES-256-GCM) on the
// server disk, never on Shopify, and open only inside the admin panel.
const DOC_KINDS = {
  id_front: 'البطاقة الوطنية - الوجه',
  id_back: 'البطاقة الوطنية - الظهر',
  res_front: 'بطاقة السكن - الوجه',
  res_back: 'بطاقة السكن - الظهر',
};
const docsRequired = () => bool('AQSATI_DOCS_REQUIRED', true);
const docsDir = (id) => path.join(CFG.dataDir, 'aqsati-docs', id || '');
let docsKeyCache = null;
function docsKey() {
  if (docsKeyCache) return docsKeyCache;
  const f = path.join(CFG.dataDir, 'aqsati-docs.key');
  try {
    const k = Buffer.from(fs.readFileSync(f, 'utf8').trim(), 'hex');
    if (k.length === 32) return (docsKeyCache = k);
  } catch {}
  const k = crypto.randomBytes(32);
  fs.mkdirSync(CFG.dataDir, { recursive: true });
  fs.writeFileSync(f, k.toString('hex'), { mode: 0o600 });
  return (docsKeyCache = k);
}
function sealDoc(buf) {
  const iv = crypto.randomBytes(12);
  const c = crypto.createCipheriv('aes-256-gcm', docsKey(), iv);
  const enc = Buffer.concat([c.update(buf), c.final()]);
  return Buffer.concat([iv, c.getAuthTag(), enc]);
}
function openDoc(buf) {
  const d = crypto.createDecipheriv('aes-256-gcm', docsKey(), buf.subarray(0, 12));
  d.setAuthTag(buf.subarray(12, 28));
  return Buffer.concat([d.update(buf.subarray(28)), d.final()]);
}

// ---- copy of the ID photos on Amazon S3 (off the server's disk) ----------
// Files stay encrypted with our own key (AES-256-GCM) before they leave; the
// key itself is kept in Shopify (app backup), never next to the photos.
// Needs: AQSATI_DOCS_S3_BUCKET and an IAM role on the EC2 server allowed to
// s3:PutObject / GetObject / DeleteObject on that bucket. No keys in .env.
const S3 = {
  bucket: () => env('AQSATI_DOCS_S3_BUCKET', ''),
  creds: null,
  region: null,
};
const s3On = () => Boolean(S3.bucket());
const IMDS = env('AWS_IMDS', 'http://169.254.169.254');
async function imds(pathname) {
  const tok = await fetch(IMDS + '/latest/api/token', {
    method: 'PUT', headers: { 'X-aws-ec2-metadata-token-ttl-seconds': '21600' }, signal: AbortSignal.timeout(2000),
  }).then((r) => r.text());
  const r = await fetch(IMDS + pathname, { headers: { 'X-aws-ec2-metadata-token': tok }, signal: AbortSignal.timeout(2000) });
  if (!r.ok) throw new Error('imds ' + r.status);
  return r.text();
}
async function s3Creds() {
  if (process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY) {
    return { id: process.env.AWS_ACCESS_KEY_ID, secret: process.env.AWS_SECRET_ACCESS_KEY, token: process.env.AWS_SESSION_TOKEN || '' };
  }
  if (S3.creds && S3.creds.exp - Date.now() > 5 * 60e3) return S3.creds;
  const role = (await imds('/latest/meta-data/iam/security-credentials/')).split('\n')[0].trim();
  if (!role) throw new Error('no IAM role on this server');
  const j = JSON.parse(await imds('/latest/meta-data/iam/security-credentials/' + role));
  S3.creds = { id: j.AccessKeyId, secret: j.SecretAccessKey, token: j.Token, exp: Date.parse(j.Expiration) };
  return S3.creds;
}
async function s3Region() {
  if (S3.region) return S3.region;
  S3.region = env('AWS_REGION', '') || (await imds('/latest/meta-data/placement/region')).trim();
  return S3.region;
}
const sha256hex = (b) => crypto.createHash('sha256').update(b).digest('hex');
const hmac = (k, d) => crypto.createHmac('sha256', k).update(d).digest();
/** One signed S3 request (AWS Signature V4). */
async function s3Request(method, key, body = Buffer.alloc(0)) {
  const [c, region] = await Promise.all([s3Creds(), s3Region()]);
  const bucket = S3.bucket();
  const custom = env('AQSATI_DOCS_S3_ENDPOINT', ''); // tests / S3-compatible stores (path style)
  const base = custom ? new URL(custom) : new URL(`https://${bucket}.s3.${region}.amazonaws.com`);
  const enc = (x) => encodeURIComponent(x).replace(/[!'()*]/g, (ch) => '%' + ch.charCodeAt(0).toString(16).toUpperCase());
  const pathname = (custom ? '/' + enc(bucket) : '') + '/' + key.split('/').map(enc).join('/');
  const now = new Date().toISOString().replace(/[-:]|\.\d{3}/g, '');
  const payloadHash = sha256hex(body);
  const headers = { host: base.host, 'x-amz-content-sha256': payloadHash, 'x-amz-date': now };
  if (method === 'PUT') headers['x-amz-server-side-encryption'] = 'AES256';
  if (c.token) headers['x-amz-security-token'] = c.token;
  headers.authorization = s3Sign(method, pathname, headers, payloadHash, c, region);
  delete headers.host;
  const r = await fetch(base.origin + pathname, { method, headers, body: method === 'PUT' ? body : undefined, signal: AbortSignal.timeout(30000) });
  if (!r.ok && !(method === 'DELETE' && r.status === 404)) throw new Error(`s3 ${method} ${r.status}`);
  return method === 'GET' ? Buffer.from(await r.arrayBuffer()) : null;
}
/** AWS Signature V4 "Authorization" header (headers must include host, x-amz-date). */
function s3Sign(method, pathname, headers, payloadHash, c, region) {
  const now = headers['x-amz-date'];
  const day = now.slice(0, 8);
  const names = Object.keys(headers).map((n) => n.toLowerCase()).sort();
  const lower = Object.fromEntries(Object.entries(headers).map(([k, v]) => [k.toLowerCase(), String(v).trim()]));
  const canonical = [method, pathname, '', names.map((n) => `${n}:${lower[n]}\n`).join(''), names.join(';'), payloadHash].join('\n');
  const scope = `${day}/${region}/s3/aws4_request`;
  const toSign = ['AWS4-HMAC-SHA256', now, scope, sha256hex(canonical)].join('\n');
  const kSign = hmac(hmac(hmac(hmac('AWS4' + c.secret, day), region), 's3'), 'aws4_request');
  return `AWS4-HMAC-SHA256 Credential=${c.id}/${scope}, SignedHeaders=${names.join(';')}, Signature=${hmac(kSign, toSign).toString('hex')}`;
}
const s3DocKey = (id, kind) => `aqsati-docs/${id}/${kind}.bin`;

/** Every 10 min: finished Aqsati files not yet on S3 are copied there. */
let s3Busy = false;
async function syncDocsToS3() {
  if (!s3On() || s3Busy) return;
  s3Busy = true;
  try {
    await backupDocsKey();
    for (const [id, rec] of Object.entries(state.aqsatiDocs || {})) {
      if (rec.s3) continue;
      let ok = true;
      for (const kind of Object.keys(rec.kinds || {})) {
        try {
          await s3Request('PUT', s3DocKey(id, kind), fs.readFileSync(path.join(docsDir(id), kind + '.bin')));
        } catch (e) {
          ok = false;
          log('s3 put', id.slice(0, 6), kind, String(e.message || e).slice(0, 120));
        }
      }
      if (ok) { rec.s3 = Date.now(); saveState(); }
    }
    state.s3 = { ok: true, at: new Date().toISOString() };
  } catch (e) {
    state.s3 = { ok: false, at: new Date().toISOString(), error: String(e.message || e).slice(0, 120) };
    log('s3 sync', state.s3.error);
  } finally {
    s3Busy = false;
  }
}

/** The photos' key, stored once in Shopify (readable only by this app). */
async function backupDocsKey() {
  if (state.docsKeySaved) return;
  const owner = await appInstallationId();
  const r = await admin(
    `mutation K($m: [MetafieldsSetInput!]!) { metafieldsSet(metafields: $m) { userErrors { message } } }`,
    { m: [{ ownerId: owner, namespace: BACKUP_NS, key: 'docs_key', type: 'single_line_text_field', value: docsKey().toString('hex') }] },
    { prio: 'bg', retrySafe: true }
  );
  if (r.metafieldsSet?.userErrors?.length) throw new Error('docs key backup: ' + JSON.stringify(r.metafieldsSet.userErrors).slice(0, 120));
  state.docsKeySaved = Date.now();
  saveState();
}
/** Disk lost: take the key back from Shopify before a new one is made. */
async function restoreDocsKey() {
  const f = path.join(CFG.dataDir, 'aqsati-docs.key');
  if (fs.existsSync(f) || !s3On()) return;
  try {
    const owner = await appInstallationId();
    const d = await admin(`query K($id: ID!) { node(id: $id) { ... on AppInstallation { metafield(namespace: "${BACKUP_NS}", key: "docs_key") { value } } } }`, { id: owner }, { prio: 'bg' });
    const v = d.node?.metafield?.value;
    if (v && /^[a-f0-9]{64}$/.test(v)) {
      fs.writeFileSync(f, v, { mode: 0o600 });
      docsKeyCache = null;
      log('docs key restored from Shopify');
    }
  } catch (e) {
    log('docs key restore', String(e.message || e).slice(0, 120));
  }
}

/** A photo: from the disk, or from S3 if the disk copy is gone. */
async function readDocFile(id, kind) {
  const f = path.join(docsDir(id), kind + '.bin');
  try {
    return fs.readFileSync(f);
  } catch (e) {
    if (!s3On() || !state.aqsatiDocs?.[id]?.s3) throw new AppError(404, 'الصورة غير موجودة');
    const buf = await s3Request('GET', s3DocKey(id, kind));
    fs.mkdirSync(docsDir(id), { recursive: true, mode: 0o700 });
    fs.writeFileSync(f, buf, { mode: 0o600 });
    return buf;
  }
}

const missingDocs = (p) => Object.keys(DOC_KINDS).filter((k) => !p.docs?.[k]);

/** Step 2b: one photo (JPEG, base64) of the ID / residence card. */
async function aqsatiDoc(body, sessionPhone) {
  const p = aqsatiPending(String(body?.ref || ''), sessionPhone);
  if (!p.sessionId) throw new AppError(400, 'أدخل رقم الحساب أولاً');
  const kind = String(body?.kind || '');
  if (!DOC_KINDS[kind]) throw new AppError(400, 'نوع الصورة غير معروف');
  rateLimit(p.order.customer.phone, 'aqsati-doc', 30, 30 * 60e3);
  const img = Buffer.from(String(body?.image || ''), 'base64');
  const jpeg = img[0] === 0xff && img[1] === 0xd8;
  const png = img.subarray(0, 4).toString('hex') === '89504e47';
  if (!(jpeg || png) || img.length < 5000) throw new AppError(400, 'الصورة غير واضحة، صوّرها مرة ثانية');
  if (img.length > 4 * 1024 * 1024) throw new AppError(413, 'الصورة كبيرة جداً');
  p.docId = p.docId || crypto.randomBytes(16).toString('hex');
  fs.mkdirSync(docsDir(p.docId), { recursive: true, mode: 0o700 });
  fs.writeFileSync(path.join(docsDir(p.docId), kind + '.bin'), sealDoc(img), { mode: 0o600 });
  p.docs = { ...(p.docs || {}), [kind]: png ? 'png' : 'jpg' };
  saveState();
  return { ok: true, missing: missingDocs(p) };
}

/** Old uploads: unfinished ones after 2 days, finished ones after AQSATI_DOCS_DAYS (365). */
function pruneAqsatiDocs() {
  const root = docsDir();
  let ids = [];
  try {
    ids = fs.readdirSync(root);
  } catch {
    return;
  }
  const keepDays = Number(env('AQSATI_DOCS_DAYS', '365')) || 365;
  const live = new Set(Object.values(state.pending || {}).map((p) => p.docId).filter(Boolean));
  for (const id of ids) {
    const rec = state.aqsatiDocs?.[id];
    let age = 0;
    try {
      age = Date.now() - fs.statSync(path.join(root, id)).mtimeMs;
    } catch {}
    const old = rec ? Date.now() - rec.at > keepDays * 86400e3 : !live.has(id) && age > 2 * 86400e3;
    if (old) {
      fs.rmSync(path.join(root, id), { recursive: true, force: true });
      if (rec?.s3 && s3On()) {
        for (const kind of Object.keys(rec.kinds || {})) s3Request('DELETE', s3DocKey(id, kind)).catch((e) => log('s3 delete', e.message));
      }
      if (rec) delete state.aqsatiDocs[id];
    }
  }
}

/** Step 3: choose months -> Aqsati sends a code to the customer's device. */
async function aqsatiPlan(body, sessionPhone) {
  const p = aqsatiPending(String(body?.ref || ''), sessionPhone);
  if (!p.sessionId) throw new AppError(400, 'أدخل رقم الحساب أولاً');
  if (docsRequired() && missingDocs(p).length) {
    throw new AppError(400, 'ارفع صور البطاقة الوطنية وبطاقة السكن (الوجه والظهر) أولاً');
  }
  const months = Number(body?.months);
  const plan = planOptions(p.amount).find((x) => x.months === months);
  if (!plan) throw new AppError(400, 'اختر عدد الأشهر');
  await aqsatiPost('/ValidatorOfInstallment', {
    sessionId: p.sessionId,
    amount: plan.finalAmount,
    countOfMonth: plan.months,
  });
  // The customer's tick under the photos ("these are mine, correct, I'm responsible").
  if (body?.declared === true) p.declaredAt = Date.now();
  Object.assign(p, { stage: 'otp', plan, otpTries: 0 });
  saveState();
  return { ok: true, plan, message: 'أرسلت أقساطي رمز تحقق إلى جهازك المسجّل لديها' };
}

/** Step 4: code -> installment created -> Shopify order created as paid. */
async function aqsatiConfirm(body, sessionPhone) {
  const ref = String(body?.ref || '');
  const p = aqsatiPending(ref, sessionPhone);
  if (p.stage === 'done') return { status: 'created', orderName: p.orderName, plan: p.plan };
  if (p.stage !== 'otp' || !p.plan) throw new AppError(400, 'اختر خطة التقسيط أولاً');
  const otp = String(body?.otp || '').replace(/[٠-٩]/g, (c) => '٠١٢٣٤٥٦٧٨٩'.indexOf(c)).replace(/\D/g, '');
  if (otp.length < 4 || otp.length > 8) throw new AppError(400, 'أدخل رمز التحقق');
  if (++p.otpTries > 5) throw new AppError(429, 'محاولات كثيرة، ابدأ من جديد');
  if (p.stage === 'creating') throw new AppError(409, 'جاري تسجيل الطلب، انتظر لحظة');

  const note = p.order.customer.name;
  const inst = await aqsatiPost('/CreateInstallment', { sessionId: p.sessionId, OTP: Number(otp), Note: note });
  p.stage = 'creating';
  p.installmentId = inst?.installmentId;
  saveState();
  try {
    const created = await createShopifyOrder(p.order, p.priced, {
      paid: true,
      gatewayRef: String(inst?.installmentId ?? inst?.operationId ?? ''),
      aqsati: { plan: p.plan, installmentId: inst?.installmentId, identity: p.identity, docId: p.docId },
    });
    Object.assign(p, { stage: 'done', orderName: created.orderName });
    await recordPointsRedeem(p.order, p.priced, created);
    if (p.docId) {
      state.aqsatiDocs = state.aqsatiDocs || {};
      state.aqsatiDocs[p.docId] = {
        orderName: created.orderName,
        name: p.order.customer.name,
        phone: p.order.customer.phone,
        identity: p.identity,
        kinds: p.docs,
        declaredAt: p.declaredAt || null,
        at: Date.now(),
      };
    }
    state.idempotency[p.order.idempotencyKey] = {
      at: Date.now(),
      result: { status: 'created', orderName: created.orderName, total: created.total, currency: created.currency },
    };
    saveState();
    return { status: 'created', orderName: created.orderName, plan: p.plan };
  } catch (e) {
    p.stage = 'paid_not_created';
    saveState();
    log('AQSATI APPROVED BUT ORDER NOT CREATED', ref, inst?.installmentId, e.message);
    throw new AppError(502, `تمت الموافقة على التقسيط لكن تعذّر تسجيل الطلب تلقائياً. احتفظ بالرمز ${ref.slice(0, 10)} وتواصل مع المتجر.`);
  }
}

// ---------------------------------------------------------- validation ---

class AppError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

function normalizePhone(p) {
  let d = String(p || '')
    .replace(/[٠-٩]/g, (c) => '٠١٢٣٤٥٦٧٨٩'.indexOf(c))
    .replace(/[۰-۹]/g, (c) => '۰۱۲۳۴۵۶۷۸۹'.indexOf(c))
    .replace(/[^\d+]/g, '');
  if (d.startsWith('+964')) d = '0' + d.slice(4);
  else if (d.startsWith('00964')) d = '0' + d.slice(5);
  else if (d.startsWith('964')) d = '0' + d.slice(3);
  if (/^7\d{9}$/.test(d)) d = '0' + d;
  return /^07[3-9]\d{8}$/.test(d) ? '+964' + d.slice(1) : null;
}

const str = (v, max) => (typeof v === 'string' ? v.trim().slice(0, max) : '');

function validateOrder(body, opts = {}) {
  const o = body || {};
  const lines = Array.isArray(o.lines) ? o.lines : [];
  if (!lines.length || lines.length > 30) throw new AppError(400, 'السلة فارغة');
  const cleanLines = lines.map((l) => {
    const q = Number(l.quantity);
    if (!/^gid:\/\/shopify\/ProductVariant\/\d+$/.test(String(l.variantId)) || !Number.isInteger(q) || q < 1 || q > 20) {
      throw new AppError(400, 'بيانات السلة غير صحيحة');
    }
    const a = l.addons && typeof l.addons === 'object' ? l.addons : null;
    const addons = a && (a.cover === true || a.protector === true)
      ? { cover: a.cover === true, protector: a.protector === true, note: a.cover === true ? str(a.note, 100) : '' }
      : null;
    return { variantId: l.variantId, quantity: q, ...(addons ? { addons } : {}) };
  });
  const name = str(o.customer?.name, 80);
  if (name.length < 3) throw new AppError(400, 'اكتب الاسم الكامل');
  const phone = normalizePhone(o.customer?.phone);
  if (!phone) throw new AppError(400, 'رقم الهاتف غير صحيح، مثال: 07701234567');
  const email = str(o.customer?.email, 120);
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new AppError(400, 'البريد الإلكتروني غير صحيح');

  const delivery = o.delivery === 'pickup' ? 'pickup' : 'shipping';
  if (delivery === 'pickup' && !CFG.pickup.enabled) throw new AppError(400, 'الاستلام من المتجر غير متاح حالياً');

  let address = null;
  if (delivery === 'shipping' && opts.skipAddress) {
    const city = WASEET_CITY.get(Number(o.address?.cityId));
    if (city) address = { governorate: city.name, area: '', cityId: Number(o.address.cityId), regionId: 0, street: '', landmark: '' };
  } else if (delivery === 'shipping') {
    // Governorate and region must come from the Al-Waseet list.
    const cityId = Number(o.address?.cityId);
    const regionId = Number(o.address?.regionId);
    const city = WASEET_CITY.get(cityId);
    if (!city) throw new AppError(400, 'اختر المحافظة من القائمة');
    const regionName = city.regions.get(regionId);
    if (!regionName) throw new AppError(400, 'اختر المنطقة من القائمة');
    address = {
      governorate: city.name,
      area: regionName,
      cityId,
      regionId,
      street: str(o.address?.street, 160),
      landmark: str(o.address?.landmark, 160),
    };
    if (!opts.skipPayment && address.landmark.length < 3) throw new AppError(400, 'اكتب أقرب نقطة دالة لعنوانك');
  }

  const payment = ['cod', 'card', 'aqsati'].includes(o.payment) ? o.payment : null;
  if (!payment) throw new AppError(400, 'اختر طريقة الدفع');
  if (opts.skipPayment) {
    // Discount check only: payment is chosen later.
  } else if (payment === 'cod' && !CFG.cod) throw new AppError(400, 'الدفع عند الاستلام غير متاح');
  if (payment === 'card' && !hyperpayEnabled()) throw new AppError(400, 'الدفع بالبطاقة غير متاح حالياً');
  if (payment === 'aqsati' && (!aqsatiEnabled() || !opts.allowAqsati)) {
    throw new AppError(400, 'أقساطي غير متاح حالياً');
  }

  const idempotencyKey = str(o.idempotencyKey, 64);
  if (!/^[A-Za-z0-9-]{16,64}$/.test(idempotencyKey)) throw new AppError(400, 'طلب غير صالح');

  return {
    lines: cleanLines,
    customer: { name, phone, email },
    delivery,
    address,
    payment,
    note: str(o.note, 500),
    discountCode: cleanCode(o.discountCode),
    usePoints: o.usePoints === true,
    marketing: o.marketing === true,
    idempotencyKey,
    _device: currentDevice(),
  };
}

// ------------------------------------------------------- device lock ---
// The app sends X-Device-Id = sha256 of Android's ID for this app (it stays
// the same after a new phone number, a new account or a reinstall; only a
// factory reset changes it). Kept salted+hashed again here, never raw.
const { AsyncLocalStorage } = require('node:async_hooks');
const reqContext = new AsyncLocalStorage();
function deviceFromHeader(req) {
  const raw = String(req.headers['x-device-id'] || '').toLowerCase();
  if (!/^[a-f0-9]{64}$/.test(raw)) return null;
  return crypto.createHmac('sha256', 'jf-device:' + (CFG.clientSecret || CFG.appKey || '')).update(raw).digest('base64url').slice(0, 32);
}
const currentDevice = () => reqContext.getStore()?.device || null;

/** Phones seen on each device (last 10), to spot one phone used for many accounts. */
function rememberDevicePhone(phone) {
  const dev = currentDevice();
  if (!dev || !phone) return;
  state.devicePhones = state.devicePhones || {};
  const list = state.devicePhones[dev] || [];
  if (list[0] === phone) return;
  state.devicePhones[dev] = [phone, ...list.filter((x) => x !== phone)].slice(0, 10);
  saveState();
}

// ---------------------------------------------------------- rate limits ---

const hits = new Map();
function rateLimit(ip, key, max, windowMs) {
  const k = `${key}:${ip}`;
  const now = Date.now();
  const arr = (hits.get(k) || []).filter((t) => now - t < windowMs);
  if (arr.length >= max) throw new AppError(429, 'محاولات كثيرة، انتظر قليلاً ثم حاول مجدداً');
  arr.push(now);
  hits.set(k, arr);
}
setInterval(() => {
  const now = Date.now();
  for (const [k, arr] of hits) if (!arr.some((t) => now - t < 3600e3)) hits.delete(k);
}, 600e3).unref();

