const ordersInFlight = new Map(); // idempotency key -> promise
async function handleOrder(body, ip, sessionPhone) {
  const key = typeof body?.idempotencyKey === 'string' ? body.idempotencyKey : null;
  // The same checkout sent twice at once (double tap, retry after a slow
  // network): the second waits for the first instead of making another order.
  if (key && ordersInFlight.has(key)) return ordersInFlight.get(key);
  const p = handleOrderOnce(body, ip, sessionPhone);
  if (key) {
    ordersInFlight.set(key, p);
    p.finally(() => ordersInFlight.delete(key)).catch(() => {});
  }
  return p;
}
async function handleOrderOnce(body, ip, sessionPhone) {
  if (otpEnabled() && !sessionPhone) throw new AppError(401, 'سجّل الدخول برقم هاتفك أولاً');
  assertOrdersOpen();
  const order = validateOrder(body);
  // The verified number is the order's phone, whatever the form says.
  if (sessionPhone) order.customer.phone = sessionPhone;

  const prior = state.idempotency[order.idempotencyKey];
  // A card attempt that was never paid must not stick: if the customer then
  // switches to cash on delivery (same checkout, same key) it is a new order.
  const unpaidCard = prior?.result?.status === 'payment_required' && order.payment !== 'card';
  if (prior && !unpaidCard) return prior.result;
  if (unpaidCard) delete state.idempotency[order.idempotencyKey];

  rateLimit(ip, 'order', CFG.ordersPerIp, 10 * 60e3);
  rateLimit(order.customer.phone, 'order-phone', 4, 10 * 60e3);

  if (order.usePoints && order.payment === 'cod') {
    const result = await placeOrderWithPoints(order);
    state.idempotency[order.idempotencyKey] = { at: Date.now(), result };
    saveState();
    return result;
  }

  const priced = await priceOrder(order);
  // Card / Aqsati with points: priced here, deducted once the order exists.
  await applyPointsDiscount(order, priced);
  const { fee, discount, total } = orderTotals(order, priced);

  let result;
  if (order.payment === 'card') {
    const ref = 'JF' + crypto.randomBytes(6).toString('hex').toUpperCase();
    const hp = await hyperpayPrepare(total, ref, order);
    const token = crypto.randomBytes(18).toString('base64url');
    state.pending[token] = {
      at: Date.now(),
      order,
      checkoutId: hp.checkoutId,
      integrity: hp.integrity,
      amount: total,
      priced,
      ref,
      status: 'waiting',
    };
    result = {
      status: 'payment_required',
      paymentUrl: `${CFG.publicUrl}/pay/${token}`,
      total,
      discount,
      deliveryFee: fee,
      currency: priced.currency,
    };
  } else {
    const created = await createShopifyOrder(order, priced, { paid: false });
    const redirectUrl = order.payment === 'aqsati' ? aqsatiUrl(order, created) : null;
    result = {
      status: 'created',
      ...(redirectUrl ? { redirectUrl } : {}),
      orderName: created.orderName,
      total: created.total,
      discount: created.discount,
      deliveryFee: created.deliveryFee,
      currency: created.currency,
      message:
        order.payment === 'aqsati'
          ? redirectUrl
            ? 'تم تسجيل طلبك. أكمل خطوات التقسيط في صفحة أقساطي.'
            : CFG.aqsati.note
          : order.delivery === 'pickup'
            ? CFG.texts.successPickup
            : CFG.texts.success,
    };
  }
  state.idempotency[order.idempotencyKey] = { at: Date.now(), result };
  saveState();
  return result;
}

