// --------------------------------------------------------------- reviews ---
// Verified-buyer reviews (Shopify metaobject "app_review": product, rating,
// comment, name, customer, order). Hide one from the admin app or by setting
// it to draft in Shopify. Ratings shown = app reviews + Quoli's existing ones.

const REVIEWS_QUERY = `
query Reviews($after: String) {
  metaobjects(type: "app_review", first: 250, after: $after, sortKey: "updated_at", reverse: true) {
    pageInfo { hasNextPage endCursor }
    nodes {
      id updatedAt
      capabilities { publishable { status } }
      fields { key value reference { ... on Product { handle title } } }
    }
  }
}`;
const QUOLI_QUERY = `
query QuoliRatings($after: String) {
  products(first: 250, after: $after, query: "status:active") {
    pageInfo { hasNextPage endCursor }
    nodes {
      handle
      rating: metafield(namespace: "reviews", key: "rating") { value }
      count: metafield(namespace: "reviews", key: "rating_count") { value }
      widget: metafield(namespace: "quoli-ugc", key: "reviewWidget") { value }
      snap: metafield(namespace: "quoli-ugc", key: "aiSnapshot") { value }
    }
  }
}`;
const REVIEW_CREATE = `
mutation ReviewCreate($m: MetaobjectCreateInput!) {
  metaobjectCreate(metaobject: $m) { metaobject { id } userErrors { field message } }
}`;
const REVIEW_UPDATE = `
mutation ReviewUpdate($id: ID!, $m: MetaobjectUpdateInput!) {
  metaobjectUpdate(id: $id, metaobject: $m) { metaobject { id } userErrors { field message } }
}`;

let reviewsCache = { at: 0, list: null };
function allReviews(force = false) {
  if (!force && reviewsCache.list && Date.now() - reviewsCache.at < 5 * 60e3) return Promise.resolve(reviewsCache.list);
  return force ? loadReviews(true) : singleFlight('reviews', () => loadReviews(false));
}
async function loadReviews(force) {
  const list = [];
  let after = null;
  for (let page = 0; page < 20; page++) {
    const d = await admin(REVIEWS_QUERY, { after });
    for (const n of d.metaobjects?.nodes || []) {
      const f = Object.fromEntries(n.fields.map((x) => [x.key, x]));
      list.push({
        id: n.id,
        active: (n.capabilities?.publishable?.status || 'ACTIVE') === 'ACTIVE',
        handle: f.product?.reference?.handle || '',
        product: f.product?.reference?.title || '',
        rating: Math.max(1, Math.min(5, Number(f.rating?.value || 0))),
        comment: f.comment?.value || '',
        name: f.name?.value || '',
        customer: f.customer?.value || '',
        order: f.order?.value || '',
        at: n.updatedAt,
      });
    }
    if (!d.metaobjects?.pageInfo?.hasNextPage) break;
    after = d.metaobjects.pageInfo.endCursor;
  }
  reviewsCache = { at: Date.now(), list };
  return list;
}

let quoliCache = { at: 0, map: null };
function quoliRatings() {
  if (quoliCache.map && Date.now() - quoliCache.at < 30 * 60e3) return Promise.resolve(quoliCache.map);
  return singleFlight('quoli', loadQuoli);
}
/** A store reviewer's name as the app shows it: first name only; an email,
 *  a phone number or anything odd becomes "زبون". */
function reviewerName(a) {
  const s = String(a || '').trim();
  if (!s || /@|\d{3,}|https?:/i.test(s)) return 'زبون';
  return s.split(/\s+/)[0].slice(0, 20);
}
async function loadQuoli() {
  const map = {};
  const texts = {}; // handle -> reviews written on the website (Quoli)
  let after = null;
  for (let page = 0; page < 20; page++) {
    const d = await admin(QUOLI_QUERY, { after });
    for (const n of d.products?.nodes || []) {
      let avg = 0;
      let count = 0;
      try {
        avg = Number(JSON.parse(n.rating?.value || '{}').value || 0);
      } catch {}
      count = Number(n.count?.value || 0);
      if (!count && n.widget?.value) {
        try {
          const w = JSON.parse(n.widget.value);
          count = Number(w.reviewCount || 0);
          avg = avg || Number(w.avgRating || 0);
        } catch {}
      }
      if (avg > 0 && count > 0) map[n.handle] = [avg, count];
      try {
        const snap = n.snap?.value ? JSON.parse(n.snap.value) : null;
        const list = (snap?.reviews || [])
          .map((r) => ({
            name: reviewerName(r.author),
            rating: Math.max(1, Math.min(5, Math.round(Number(r.rating) || 0))),
            title: String(r.title || '').replace(/\s+/g, ' ').trim().slice(0, 120),
            comment: String(r.body || '').replace(/\s+/g, ' ').trim().slice(0, 600),
            at: /^\d{4}-\d{2}-\d{2}/.test(String(r.date || '')) ? String(r.date).slice(0, 10) : null,
            verified: r.verified === true,
            source: 'store',
          }))
          .filter((r) => r.rating && (r.comment || r.title));
        if (list.length) texts[n.handle] = list.slice(0, 30);
      } catch {}
    }
    if (!d.products?.pageInfo?.hasNextPage) break;
    after = d.products.pageInfo.endCursor;
  }
  quoliCache = { at: Date.now(), map, texts };
  return map;
}

/** handle -> [average, count] across app reviews + Quoli. */
async function handleRatings() {
  const [reviews, quoli] = await Promise.all([allReviews().catch(() => []), quoliRatings().catch(() => ({}))]);
  const sum = {};
  for (const [h, [avg, count]] of Object.entries(quoli)) sum[h] = [avg * count, count];
  for (const r of reviews) {
    if (!r.active || !r.handle) continue;
    const s = (sum[r.handle] = sum[r.handle] || [0, 0]);
    s[0] += r.rating;
    s[1] += 1;
  }
  const ratings = {};
  for (const [h, [total, count]] of Object.entries(sum)) {
    if (count) ratings[h] = [Math.round((total / count) * 10) / 10, count];
  }
  return { ratings };
}

/** Delivered orders of this phone that contain the product (verified buyer). */
async function deliveredPurchase(phone, handle) {
  const c = await customerByPhone(phone);
  if (!c) return null;
  const d = await myOrders(c.id.split('/').pop());
  for (const o of d.orders?.nodes || []) {
    if (orderStep(o).step !== 4) continue;
    const li = (o.lineItems?.nodes || []).find((x) => x.product?.handle === handle);
    if (li) return { customer: c, order: o.name, productId: li.product.id };
  }
  return { customer: c, order: null };
}

async function handleReviews(handle, phone) {
  if (!/^[a-z0-9][a-z0-9-]{0,199}$/.test(handle)) throw new AppError(400, 'منتج غير صالح');
  const [reviews, ratings] = await Promise.all([allReviews(), handleRatings()]);
  const mine = reviews.filter((r) => r.handle === handle);
  const shown = mine.filter((r) => r.active);
  let can = false;
  let my = null;
  if (phone) {
    try {
      const p = await deliveredPurchase(phone, handle);
      can = Boolean(p?.order);
      const cid = p?.customer?.id;
      const r = cid && mine.find((x) => x.customer === cid);
      if (r) my = { rating: r.rating, comment: r.comment };
    } catch {}
  }
  const [average, count] = ratings.ratings[handle] || [0, 0];
  const app = shown.map((r) => ({ name: r.name || 'زبون', rating: r.rating, comment: r.comment, at: r.at, verified: true, source: 'app' }));
  const store = quoliCache.texts?.[handle] || [];
  // Newest first, app and website together.
  const list = [...app, ...store].sort((a, b) => String(b.at || '').localeCompare(String(a.at || ''))).slice(0, 30);
  const dist = [0, 0, 0, 0, 0]; // 5★ .. 1★, from the written reviews
  for (const r of [...app, ...store]) if (r.rating >= 1 && r.rating <= 5) dist[5 - r.rating]++;
  return {
    average,
    count,
    dist,
    canReview: can,
    mine: my,
    reviews: list,
  };
}

async function submitReview(phone, body) {
  const handle = String(body?.handle || '').toLowerCase();
  const rating = Math.trunc(Number(body?.rating));
  const comment = String(body?.comment || '').replace(/\s+/g, ' ').trim().slice(0, 500);
  if (!/^[a-z0-9][a-z0-9-]{0,199}$/.test(handle) || !(rating >= 1 && rating <= 5)) {
    throw new AppError(400, 'اختر عدد النجوم');
  }
  const p = await deliveredPurchase(phone, handle);
  if (!p?.order) throw new AppError(403, 'التقييم متاح بعد استلام هذا المنتج');
  const c = p.customer;
  const name = [c.firstName, (c.lastName || '').slice(0, 1)].filter(Boolean).join(' ') + ((c.lastName || '') ? '.' : '');
  const fields = [
    { key: 'product', value: p.productId },
    { key: 'rating', value: String(rating) },
    { key: 'comment', value: comment },
    { key: 'name', value: name.trim() || 'زبون' },
    { key: 'customer', value: c.id },
    { key: 'order', value: p.order },
  ];
  const existing = (await allReviews(true)).find((r) => r.handle === handle && r.customer === c.id);
  if (existing) {
    const r = await admin(REVIEW_UPDATE, { id: existing.id, m: { fields } });
    const errs = r.metaobjectUpdate?.userErrors || [];
    if (errs.length) throw new AppError(502, 'تعذّر حفظ التقييم');
  } else {
    const r = await admin(REVIEW_CREATE, {
      m: { type: 'app_review', capabilities: { publishable: { status: 'ACTIVE' } }, fields },
    });
    const errs = r.metaobjectCreate?.userErrors || [];
    if (errs.length) {
      log('review create', JSON.stringify(errs).slice(0, 300));
      throw new AppError(502, 'تعذّر حفظ التقييم');
    }
  }
  reviewsCache = { at: 0, list: null };
  log('review', handle, rating);
  return { ok: true };
}

