async function adminCustomer(phoneRaw) {
  const phone = normalizePhone(phoneRaw);
  if (!phone) throw new AppError(400, 'رقم الهاتف غير صحيح');
  const c = await customerByPhone(phone);
  if (!c) throw new AppError(404, 'لا يوجد زبون بهذا الرقم');
  const recent = await admin(MY_ORDERS_QUERY, { q: `customer_id:${c.id.split('/').pop()}` });
  const orders = recent.orders?.nodes || [];
  const ledger = (await reconcileCustomer(c.id, orders)) || (await loadLedger(c.id)).ledger;
  const balance = ledgerBalance(ledger);
  const label = { earn: 'طلب مكتمل', redeem: 'استبدال نقاط', welcome: 'هدية الانضمام بدعوة', referral: 'دعوة صديق', adjust: 'تعديل من الإدارة', tier: 'هدية مستوى VIP', wheel: 'عجلة الحظ' };
  const mult = tierMult(tierRank(ledger.tier?.id));
  return {
    name: [c.firstName, c.lastName].filter(Boolean).join(' '),
    phone,
    orders: Number(c.numberOfOrders || 0),
    balance,
    value: balance * LOY.pointValue,
    tier: TIERS.enabled ? tierInfo(ledger.tier) : null,
    pending: orders.reduce((a, o) => a + orderPointsTarget(o, mult).pending, 0),
    code: referralCode(c.id),
    history: ledger.entries
      .filter((e) => e.p)
      .sort((a, b) => String(b.upd || b.at).localeCompare(String(a.upd || a.at)))
      .slice(0, 60)
      .map((e) => ({ title: label[e.t] || 'نقاط', order: e.o || null, note: e.note || '', points: e.p, at: e.upd || e.at })),
  };
}

async function adminAdjustPoints(body) {
  const phone = normalizePhone(body?.phone);
  const pts = Math.trunc(Number(body?.points));
  if (!phone || !pts || Math.abs(pts) > 1e7) throw new AppError(400, 'بيانات غير صحيحة');
  const c = await customerByPhone(phone);
  if (!c) throw new AppError(404, 'لا يوجد زبون بهذا الرقم');
  return withLoyaltyLock(c.id, async () => {
    const { ledger } = await loadLedger(c.id);
    const balance = ledgerBalance(ledger);
    if (balance + pts < 0) throw new AppError(400, `لا يمكن الخصم: الرصيد ${balance} نقطة`);
    setEntry(ledger, 'adj:' + Date.now(), pts, { t: 'adjust', note: String(body?.note || '').slice(0, 120) });
    await saveLedger(c.id, ledger);
    log('admin: points', phone.slice(-4), pts);
    return { ok: true, balance: balance + pts };
  });
}

// --------------------------------------------------- crash reports ---
// The app sends its errors here (message, stack, version, phone model);
// the same error is grouped, newest first, shown in the admin app.
function recordCrash(body, ip) {
  const clean = (v, n) => String(v || '').replace(/[\u0000-\u0008\u000B-\u001F]/g, '').slice(0, n);
  const error = clean(body?.error, 500);
  if (!error) throw new AppError(400, 'empty');
  const stack = clean(body?.stack, 4000);
  const version = clean(body?.version, 20);
  const sig = crypto.createHash('sha1').update(error.split('\n')[0] + '|' + stack.split('\n').slice(0, 3).join('|') + '|' + version).digest('hex').slice(0, 16);
  state.crashes = state.crashes || [];
  const i = state.crashes.findIndex((c) => c.sig === sig);
  const now = new Date().toISOString();
  if (i >= 0) {
    const c = state.crashes.splice(i, 1)[0];
    c.count++;
    c.last = now;
    c.model = clean(body?.model, 60) || c.model;
    state.crashes.unshift(c);
  } else {
    state.crashes.unshift({
      sig,
      error,
      stack,
      version,
      model: clean(body?.model, 60),
      android: clean(body?.android, 20),
      screen: clean(body?.screen, 60),
      fatal: body?.fatal === true,
      count: 1,
      first: now,
      last: now,
    });
    log('crash', version, error.split('\n')[0].slice(0, 160));
  }
  state.crashes = state.crashes.slice(0, 100);
  saveState();
  return { ok: true };
}

// ------------------------------------------------ backups & health ---
// Daily: a compressed copy of the data (points requests, codes, devices,
// stats…) kept 7 days on the server AND in Shopify (app-private data of the
// "Ji Fire Order" app, readable only by it). A new/empty server restores
// itself from Shopify automatically. Secrets are never included.
const BACKUP_DIR = path.join(CFG.dataDir, 'backups');
const BACKUP_NS = 'jifire_backup';
const CHUNK = 60000; // chars per metafield (limit 64KB)

async function appInstallationId() {
  const d = await admin('{ currentAppInstallation { id } }');
  return d.currentAppInstallation.id;
}

function backupPayload() {
  const settings = {};
  for (const [k, , secret] of EDITABLE) if (!secret && process.env[k] != null) settings[k] = process.env[k];
  return zlib.gzipSync(JSON.stringify({ v: 1, at: new Date().toISOString(), state, settings })).toString('base64');
}

async function runBackup() {
  const b64 = backupPayload();
  const day = new Date().toISOString().slice(0, 10);
  // 1) local, 7 days
  try {
    fs.mkdirSync(BACKUP_DIR, { recursive: true });
    fs.writeFileSync(path.join(BACKUP_DIR, `state-${day}.json.gz.b64`), b64);
    const files = fs.readdirSync(BACKUP_DIR).filter((f) => f.startsWith('state-')).sort();
    for (const f of files.slice(0, Math.max(0, files.length - 7))) fs.unlinkSync(path.join(BACKUP_DIR, f));
  } catch (e) {
    log('backup local failed', e.message);
  }
  // 2) Shopify (off the server: survives a lost disk)
  const owner = await appInstallationId();
  const parts = [];
  for (let i = 0; i < b64.length; i += CHUNK) parts.push(b64.slice(i, i + CHUNK));
  if (parts.length > 60) throw new Error('backup too large: ' + b64.length);
  const fields = parts.map((v, i) => ({ ownerId: owner, namespace: BACKUP_NS, key: `part_${i}`, type: 'multi_line_text_field', value: v }));
  fields.push({
    ownerId: owner,
    namespace: BACKUP_NS,
    key: 'meta',
    type: 'json',
    value: JSON.stringify({ at: new Date().toISOString(), parts: parts.length, bytes: b64.length }),
  });
  for (let i = 0; i < fields.length; i += 25) {
    const r = await admin(
      `mutation B($m: [MetafieldsSetInput!]!) { metafieldsSet(metafields: $m) { userErrors { field message } } }`,
      { m: fields.slice(i, i + 25) }
    );
    const errs = r.metafieldsSet?.userErrors || [];
    if (errs.length) throw new Error(JSON.stringify(errs).slice(0, 300));
  }
  state.backup = { at: new Date().toISOString(), bytes: b64.length, parts: parts.length, ok: true };
  saveState();
  log('backup ok', parts.length, 'parts', b64.length, 'bytes');
}

async function restoreFromShopify() {
  const owner = await appInstallationId();
  const meta = await admin(
    `query M($id: ID!) { node(id: $id) { ... on AppInstallation { metafield(namespace: "${BACKUP_NS}", key: "meta") { value } } } }`,
    { id: owner }
  );
  const m = JSON.parse(meta.node?.metafield?.value || 'null');
  if (!m?.parts) return false;
  let b64 = '';
  for (let i = 0; i < m.parts; i++) {
    const d = await admin(
      `query P($id: ID!, $k: String!) { node(id: $id) { ... on AppInstallation { metafield(namespace: "${BACKUP_NS}", key: $k) { value } } } }`,
      { id: owner, k: `part_${i}` }
    );
    b64 += d.node?.metafield?.value || '';
  }
  const data = JSON.parse(zlib.gunzipSync(Buffer.from(b64, 'base64')).toString('utf8'));
  if (!data?.state) return false;
  Object.assign(state, data.state);
  writeStateNow();
  log('restored from Shopify backup of', m.at);
  return m.at;
}

function diskInfo() {
  try {
    const st = fs.statfsSync(CFG.dataDir);
    const total = st.blocks * st.bsize;
    const free = st.bavail * st.bsize;
    return { totalGb: +(total / 1e9).toFixed(1), freeGb: +(free / 1e9).toFixed(1), freePct: Math.round((free / total) * 100) };
  } catch {
    return null;
  }
}

let maintBusy = false;
async function dailyMaintenance() {
  if (maintBusy) return;
  const day = new Date().toISOString().slice(0, 10);
  if (state.maintDay === day) return;
  maintBusy = true;
  try {
    pruneState();
    state.maintDay = day;
    saveState();
    await runBackup();
  } catch (e) {
    state.backup = { ...(state.backup || {}), ok: false, error: String(e.message || e).slice(0, 200), tried: new Date().toISOString() };
    saveState();
    log('backup failed', String(e.message || e).slice(0, 300));
  } finally {
    maintBusy = false;
  }
}

if (require.main === module) {
  // Fresh server with no data file: bring the data back from Shopify first.
  setTimeout(async () => {
    try {
      if (!state.maintDay && !Object.keys(state.push || {}).length) await restoreFromShopify();
    } catch (e) {
      log('restore skipped', String(e.message || e).slice(0, 200));
    }
    dailyMaintenance();
  }, 20000).unref();
  setInterval(dailyMaintenance, 60 * 60e3).unref();
}

// ------------------------------------------------ admin: send a push ---
// "إشعار للزبائن": everyone (topic "all" = every install, also guests),
// a level and above, signed-in customers, or one phone to test.
const AUDIENCES = {
  all: 'كل مستخدمي التطبيق',
  registered: 'المسجّلين فقط',
  silver: '🥈 فضي فما فوق',
  gold: '🥇 ذهبي فما فوق',
  vip: '💎 VIP فقط',
  test: 'رقم للتجربة',
};

function audiencePhones(aud) {
  const phones = Object.keys(state.push || {});
  if (aud === 'registered') return phones;
  const min = tierRank(aud);
  return phones.filter((ph) => tierRank(state.tierPhones?.[ph] || 'bronze') >= min && state.tierPhones?.[ph]);
}

function pushAudienceCounts() {
  const n = (list) => list.reduce((a, ph) => a + (state.push?.[ph]?.length || 0), 0);
  return {
    registered: n(audiencePhones('registered')),
    silver: n(audiencePhones('silver')),
    gold: n(audiencePhones('gold')),
    vip: n(audiencePhones('vip')),
    labels: AUDIENCES,
  };
}

