async function adminSendPush(body) {
  if (!pushEnabled()) throw new AppError(400, 'الإشعارات تحتاج مفتاح Firebase أولاً (الإعدادات ← إشعارات Firebase)');
  const title = String(body?.title || '').trim().slice(0, 80);
  const text = String(body?.body || '').trim().slice(0, 300);
  const aud = Object.hasOwn(AUDIENCES, body?.audience) ? body.audience : null;
  if (!title || !text) throw new AppError(400, 'اكتب العنوان والنص');
  if (!aud) throw new AppError(400, 'اختر لمن يُرسل الإشعار');
  let image = String(body?.image || '').trim();
  if (image && !/^https:\/\/[^\s"'<>]{4,600}$/.test(image)) throw new AppError(400, 'رابط الصورة غير صالح (يجب أن يبدأ بـ https)');
  const product = String(body?.product || '').toLowerCase();
  if (product && !/^[a-z0-9][a-z0-9-]{0,199}$/.test(product)) throw new AppError(400, 'منتج غير صالح');
  const data = product ? { product } : {};
  if (image) data.image = image;
  const msg = { title, body: text, data, image };
  let sent = 0;
  let failed = 0;
  if (aud === 'all') {
    const r = await sendPush({ topic: 'all' }, msg);
    if (r !== 'ok') throw new AppError(502, 'تعذّر الإرسال، تأكد من مفتاح Firebase');
    sent = -1; // topic: Firebase delivers to every install
  } else {
    let phones;
    if (aud === 'test') {
      const ph = normalizePhone(body?.phone);
      if (!ph) throw new AppError(400, 'اكتب رقم التجربة');
      if (!state.push?.[ph]?.length) throw new AppError(404, 'هذا الرقم غير مسجّل دخول بالتطبيق أو لم يفعّل الإشعارات');
      phones = [ph];
    } else {
      phones = audiencePhones(aud);
    }
    ({ sent, failed } = await pushMany(tokensOf(phones), msg));
    if (!sent && !failed) throw new AppError(400, 'لا يوجد أجهزة بهذه الفئة حالياً');
  }
  if (aud !== 'test') {
    state.adminPushes = [{ at: new Date().toISOString(), title, body: text, audience: aud, product, sent, failed }, ...(state.adminPushes || [])].slice(0, 30);
    saveState();
  }
  log('admin: push', aud, sent, failed);
  return { ok: true, sent, failed };
}

// Aqsati ID photos: list, one customer, one photo. Admin login only.
async function adminDocs(req, res, p, url) {
  const secure = { 'Cache-Control': 'no-store', 'X-Frame-Options': 'DENY', 'X-Robots-Tag': 'noindex' };
  if (!adminSessionOk(req)) {
    res.writeHead(302, { Location: '/admin', ...secure });
    return res.end();
  }
  const esc = (x) => String(x ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
  const m = /^\/admin\/docs(?:\/([a-f0-9]{32}))?(?:\/([a-z_]+))?$/.exec(p);
  if (!m) throw new AppError(404, 'غير موجود');
  const [, id, kind] = m;
  if (id && kind) {
    const rec = state.aqsatiDocs?.[id];
    const pend = Object.values(state.pending || {}).find((x) => x.docId === id);
    const type = (rec?.kinds || pend?.docs || {})[kind];
    if (!DOC_KINDS[kind] || !type) throw new AppError(404, 'غير موجود');
    const img = openDoc(await readDocFile(id, kind));
    log('admin: docs view', id.slice(0, 6), kind);
    res.writeHead(200, { 'Content-Type': type === 'png' ? 'image/png' : 'image/jpeg', ...secure });
    return res.end(img);
  }
  const page = (title, body) =>
    `<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(title)}</title><style>body{margin:0;background:#0A0A0C;color:#F5F5F7;font:15px system-ui,-apple-system,"Segoe UI",Tahoma,sans-serif}.wrap{max-width:900px;margin:auto;padding:16px}h1{font-size:20px;color:#E2B85A}a{color:#E2B85A;text-decoration:none}.row{display:block;background:#141417;border:1px solid #2A2A30;border-radius:16px;padding:14px;margin:10px 0;color:inherit}.mu{color:#8E8E96;font-size:13px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px}.grid figure{margin:0;background:#141417;border:1px solid #2A2A30;border-radius:16px;padding:10px}.grid img{width:100%;border-radius:10px;display:block}figcaption{margin-top:8px;font-weight:700}.back{display:inline-block;margin-bottom:8px}</style></head><body><div class="wrap">${body}</div></body></html>`;
  res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8', ...secure });
  if (id) {
    const rec = state.aqsatiDocs?.[id];
    const pend = Object.values(state.pending || {}).find((x) => x.docId === id);
    const kinds = rec?.kinds || pend?.docs;
    if (!kinds) return res.end(page('غير موجود', '<a class="back" href="/admin/docs">‹ كل المستمسكات</a><p>لا توجد صور (ربما انتهت مدة الاحتفاظ).</p>'));
    const head = rec
      ? `<h1>طلب ${esc(rec.orderName)} — ${esc(rec.name)}</h1><div class="mu">${esc(String(rec.phone).replace('+964', '0'))} · حساب أقساطي ${esc(rec.identity)} · ${new Date(rec.at).toLocaleString('ar-IQ', { timeZone: 'Asia/Baghdad' })}</div>`
      : `<h1>${esc(pend.order.customer.name)} (لم يكتمل الطلب)</h1>`;
    const dAt = rec?.declaredAt || pend?.declaredAt;
    const decl = dAt
      ? `<div class="mu" style="color:#22c55e;margin-top:6px">✓ أقرّ الزبون بصحة المستمسكات ومسؤوليته عنها — ${new Date(dAt).toLocaleString('ar-IQ', { timeZone: 'Asia/Baghdad' })}</div>`
      : '<div class="mu" style="margin-top:6px">— لا يوجد إقرار مسجّل (نسخة تطبيق قديمة)</div>';
    const figs = Object.keys(DOC_KINDS)
      .filter((k) => kinds[k])
      .map((k) => `<figure><a href="/admin/docs/${id}/${k}" target="_blank"><img loading="lazy" src="/admin/docs/${id}/${k}" alt=""></a><figcaption>${esc(DOC_KINDS[k])}</figcaption></figure>`)
      .join('');
    return res.end(page('مستمسكات', `<a class="back" href="/admin/docs">‹ كل المستمسكات</a>${head}${decl}<div class="grid" style="margin-top:14px">${figs}</div>`));
  }
  const q = String(url.searchParams.get('q') || '').trim();
  const list = Object.entries(state.aqsatiDocs || {})
    .filter(([, r]) => !q || [r.orderName, r.name, r.phone, r.identity].some((x) => String(x || '').includes(q.replace(/^0/, ''))))
    .sort((a, b) => b[1].at - a[1].at)
    .slice(0, 200)
    .map(([k, r]) => `<a class="row" href="/admin/docs/${k}"><b>${esc(r.orderName)}</b> — ${esc(r.name)}<div class="mu">${esc(String(r.phone).replace('+964', '0'))} · ${new Date(r.at).toLocaleDateString('ar-IQ', { timeZone: 'Asia/Baghdad' })}</div></a>`)
    .join('');
  return res.end(page('مستمسكات أقساطي', `<a class="back" href="/admin">‹ لوحة الإدارة</a><h1>مستمسكات أقساطي</h1><form><input name="q" value="${esc(q)}" placeholder="بحث برقم الطلب أو الاسم أو الهاتف" style="width:100%;box-sizing:border-box;padding:12px;border-radius:12px;border:1px solid #3A3A42;background:#1C1C21;color:#fff;font-size:15px"></form>${list || '<p class="mu">لا توجد مستمسكات بعد.</p>'}`));
}

async function handleAdmin(req, res, p, url) {
  // CSRF: a change to the admin can only come from the admin page itself.
  // (The cookie is SameSite=Lax as well; this also stops same-site tricks.)
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    const origin = String(req.headers.origin || '');
    const host = String(req.headers['x-forwarded-host'] || req.headers.host || '').split(',')[0].trim();
    if (origin && origin !== 'null') {
      let ok = false;
      try {
        ok = new URL(origin).host === host;
      } catch {}
      if (!ok) throw new AppError(403, 'طلب غير مسموح');
    }
  }
  if (p === '/admin/logo.png') {
    res.writeHead(200, { 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=86400' });
    return res.end(ADMIN_LOGO);
  }
  if (p === '/admin' && req.method === 'GET') {
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store', 'X-Frame-Options': 'DENY' });
    return res.end(ADMIN_HTML);
  }
  if (p === '/admin/docs' || p.startsWith('/admin/docs/')) return adminDocs(req, res, p, url);
  if (p === '/admin/login' && req.method === 'POST') {
    rateLimit(clientIp(req), 'admin', 8, 10 * 60e3);
    let body;
    try {
      body = JSON.parse(await readBody(req, 4096));
    } catch {
      throw new AppError(400, 'طلب غير صالح');
    }
    if (!adminPassOk(body?.pass)) throw new AppError(401, 'كلمة المرور غير صحيحة');
    const exp = Date.now() + 30 * 86400e3;
    res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8', 'Set-Cookie': adminCookie(`${exp}.${adminSig(exp)}`, 30 * 86400) });
    log('admin: login');
    return res.end('{"ok":true}');
  }
  if (p === '/admin/logout' && req.method === 'POST') {
    res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8', 'Set-Cookie': adminCookie('', 0) });
    return res.end('{"ok":true}');
  }
  if (p === '/admin/api/state' && req.method === 'GET') {
    requireAdmin(req);
    return send(res, 200, adminState());
  }
  if (p === '/admin/api/orders' && req.method === 'GET') {
    requireAdmin(req);
    return send(res, 200, await adminOrders());
  }
  if (p === '/admin/api/customer' && req.method === 'GET') {
    requireAdmin(req);
    return send(res, 200, await adminCustomer(url.searchParams.get('phone')));
  }
  if (p === '/admin/api/points' && req.method === 'POST') {
    requireAdmin(req);
    rateLimit(clientIp(req), 'admin-points', 30, 10 * 60e3);
    return send(res, 200, await adminAdjustPoints(JSON.parse(await readBody(req, 4096))));
  }
  if (p === '/admin/api/backup' && req.method === 'POST') {
    requireAdmin(req);
    rateLimit(clientIp(req), 'admin-backup', 6, 60 * 60e3);
    await runBackup();
    return send(res, 200, { ok: true, backup: state.backup });
  }
  if (p === '/admin/api/crashes/clear' && req.method === 'POST') {
    requireAdmin(req);
    state.crashes = [];
    saveState();
    return send(res, 200, { ok: true });
  }
  if (p === '/admin/api/abandon/test' && req.method === 'POST') {
    requireAdmin(req);
    rateLimit(clientIp(req), 'admin-abandon', 20, 60 * 60e3);
    return send(res, 200, await adminAbandonTest(JSON.parse(await readBody(req, 2048))));
  }
  if (p === '/admin/api/owner/test' && req.method === 'POST') {
    requireAdmin(req);
    rateLimit(clientIp(req), 'admin-owner', 20, 60 * 60e3);
    return send(res, 200, await adminOwnerTest(JSON.parse(await readBody(req, 2048))));
  }
  if (p === '/admin/api/products' && req.method === 'GET') {
    requireAdmin(req);
    return send(res, 200, await adminProducts(url.searchParams.get('q')));
  }
  if (p === '/admin/api/push' && req.method === 'POST') {
    requireAdmin(req);
    rateLimit(clientIp(req), 'admin-push', 20, 60 * 60e3);
    return send(res, 200, await adminSendPush(JSON.parse(await readBody(req, 8192))));
  }
  if (p === '/admin/api/reviews' && req.method === 'GET') {
    requireAdmin(req);
    const list = await allReviews(true);
    return send(res, 200, { reviews: list.slice(0, 80) });
  }
  if (p === '/admin/api/reviews/status' && req.method === 'POST') {
    requireAdmin(req);
    const body = JSON.parse(await readBody(req, 2048));
    const id = String(body?.id || '');
    if (!/^gid:\/\/shopify\/Metaobject\/\d+$/.test(id)) throw new AppError(400, 'طلب غير صالح');
    const r = await admin(REVIEW_UPDATE, { id, m: { capabilities: { publishable: { status: body?.active ? 'ACTIVE' : 'DRAFT' } } } });
    if ((r.metaobjectUpdate?.userErrors || []).length) throw new AppError(502, 'تعذّر التحديث');
    reviewsCache = { at: 0, list: null };
    return send(res, 200, { ok: true });
  }
  if (p === '/admin/api/settings' && req.method === 'POST') {
    requireAdmin(req);
    const body = JSON.parse(await readBody(req, 32 * 1024));
    const allowed = new Set(EDITABLE.map(([k]) => k));
    const changes = {};
    for (const [k, raw] of Object.entries(body?.changes || {})) {
      if (!allowed.has(k)) continue;
      let v = String(raw ?? '').trim();
      if (!v) continue;
      if (k === 'WHEEL_PRIZES' && v !== '-') {
        const rows = v.split(/\r?\n|\|/).map((x) => x.trim()).filter(Boolean);
        if (rows.length < 2 || rows.some((x) => !/^[^:|]{1,24}:\d{1,6}:\d{1,3}(\.\d+)?%?$/.test(x))) {
          throw new AppError(400, 'صيغة الجوائز: كل سطر الاسم:النقاط:النسبة، مثل 10 نقاط:10:8');
        }
        v = rows.map((x) => x.replace(/%$/, '')).join('|');
      }
      if (k === 'FIREBASE_SERVICE_ACCOUNT' && v !== '-') {
        try {
          const j = JSON.parse(v);
          if (!j.client_email || !j.private_key || !j.project_id) throw new Error('bad');
          v = Buffer.from(JSON.stringify(j)).toString('base64');
        } catch {
          throw new AppError(400, 'ملف Firebase غير صحيح: اختر ملف Service account (JSON)');
        }
      }
      changes[k] = v === '-' ? '' : v;
    }
    if (!Object.keys(changes).length) return send(res, 200, { ok: true, changed: 0 });
    saveEnv(changes);
    log('admin: settings changed', Object.keys(changes).join(','));
    send(res, 200, { ok: true, changed: Object.keys(changes).length });
    setTimeout(() => process.exit(0), 500); // systemd restarts with the new settings
    return;
  }
  return null;
}

function saveEnv(changes) {
  const file = path.join(__dirname, '.env');
  let lines = fs.existsSync(file) ? fs.readFileSync(file, 'utf8').split(/\r?\n/) : [];
  for (const [k, v] of Object.entries(changes)) {
    const clean = String(v).replace(/[\r\n]/g, '').trim();
    const line = `${k}=${clean}`;
    const i = lines.findIndex((l) => l.startsWith(`${k}=`));
    if (i >= 0) lines[i] = line;
    else lines.push(line);
  }
  fs.writeFileSync(file + '.tmp', lines.join('\n'), { mode: 0o600 });
  fs.renameSync(file + '.tmp', file);
}

// ---------------------------------------------------------------- server ---

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const log = (...a) => console.log(new Date().toISOString(), ...a);
const escapeHtml = (s) =>
  String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const formatIqd = (n) => Math.round(n).toLocaleString('en-US') + ' د.ع';

function send(res, status, body, type = 'application/json; charset=utf-8') {
  const data = type.startsWith('application/json') ? JSON.stringify(body) : body;
  res.writeHead(status, {
    'Content-Type': type,
    'Cache-Control': 'no-store',
    'X-Content-Type-Options': 'nosniff',
  });
  res.end(data);
}

function readBody(req, limit = 64 * 1024) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on('data', (c) => {
      size += c.length;
      if (size > limit) {
        reject(new AppError(413, 'الطلب كبير جداً'));
        req.destroy();
      } else chunks.push(c);
    });
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function clientIp(req) {
  const fwd = req.headers['x-forwarded-for'];
  return (fwd ? String(fwd).split(',')[0] : req.socket.remoteAddress || '').trim();
}

/** Effective minimum: the manual setting, raised to the latest release when forced. */
function appMinVersion() {
  const manual = CFG.app.minVersion;
  if (!CFG.app.forceLatest) return manual;
  return !manual || versionLess(manual, CFG.app.release) ? CFG.app.release : manual;
}

/** "3.10.2" vs "3.9" -> numeric part by part. */
function versionLess(a, b) {
  const pa = String(a || '0').split(/[.+]/).map((x) => parseInt(x, 10) || 0);
  const pb = String(b || '0').split(/[.+]/).map((x) => parseInt(x, 10) || 0);
  for (let i = 0; i < Math.max(pa.length, pb.length, 3); i++) {
    const d = (pa[i] || 0) - (pb[i] || 0);
    if (d) return d < 0;
  }
  return false;
}

// Each store gets its own update link (Play / App Store / our download link).
function updateUrlFor(req) {
  const store = String(req?.headers?.['x-app-store'] || '').toLowerCase();
  if (store === 'play') return env('APP_UPDATE_URL_PLAY', 'https://play.google.com/store/apps/details?id=com.fayez.mobile');
  if (store === 'ios') return env('APP_UPDATE_URL_IOS', '') || CFG.app.updateUrl;
  return CFG.app.updateUrl;
}

function appStatus(req) {
  const v = String(req.headers['x-app-version'] || '');
  const min = appMinVersion();
  const latest = CFG.app.latestVersion || min;
  return {
    version: v || null,
    minVersion: min || null,
    latestVersion: latest || null,
    updateUrl: updateUrlFor(req),
    message: CFG.app.updateMessage,
    forceUpdate: Boolean(min) && (!v || versionLess(v, min)),
    updateAvailable: Boolean(latest) && Boolean(v) && versionLess(v, latest),
  };
}

/** Old app versions (older ones send no version at all) can't order or log in. */
function checkAppVersion(req) {
  if (!appMinVersion()) return;
  if (appStatus(req).forceUpdate) {
    throw new AppError(426, `${CFG.app.updateMessage}\n${updateUrlFor(req)}`);
  }
}

// Old app versions can't show the update screen, but they do load banners and
// notices from us: give them an "update now" banner + notification instead.
const UPDATE_BANNER_JPG = Buffer.from('', 'base64');

function updateNoticeTime() {
  state.appUpdate = state.appUpdate || {};
  const key = appMinVersion() || 'none';
  if (!state.appUpdate[key]) {
    state.appUpdate[key] = new Date().toISOString();
    saveState();
  }
  return state.appUpdate[key];
}

function withUpdatePromo(req, kind, data) {
  if (!appMinVersion() || !appStatus(req).forceUpdate) return data;
  const link = { type: 'url', url: updateUrlFor(req) };
  if (kind === 'banners') {
    const banner = {
      id: 'app-update-' + appMinVersion(),
      title: 'حدّث التطبيق',
      image: `${CFG.publicUrl}/update-banner.jpg?v=${encodeURIComponent(appMinVersion())}`,
      aspect: 2,
      link,
      sort: -1000,
    };
    return { ...data, banners: [banner, ...(data.banners || [])] };
  }
  const at = updateNoticeTime();
  const notice = {
    id: 'app-update-' + appMinVersion(),
    title: 'تحديث جديد لتطبيق جي فاير 🔥',
    body: CFG.app.updateMessage + ' اضغط هنا للتحديث.',
    image: null,
    link,
    at,
    updatedAt: at,
  };
  return { ...data, notices: [notice, ...(data.notices || [])] };
}

const VERSION_GATED = new Set([
  '/api/config', '/api/orders', '/api/auth/otp/send', '/api/auth/otp/verify', '/api/discount/check',
  '/api/addons/quote', '/api/loyalty/me', '/api/loyalty/referral', '/api/ai/ask',
]);

function checkAppKey(req) {
  if (CFG.appKey && req.headers['x-app-key'] !== CFG.appKey) {
    throw new AppError(401, 'غير مصرّح');
  }
}

// Which Shopify queue a request waits in (see the Admin gateway): placing or
// paying an order goes first; the name shown after login is a nice-to-have.
function shopPrioOf(req) {
  const u = String(req.url || '').split('?')[0];
  if (req.method === 'POST' && (u === '/api/orders' || u === '/api/orders/cancel' || u.startsWith('/api/aqsati/'))) return { prio: 'order' };
  if (u.startsWith('/pay/')) return { prio: 'order' };
  if (u === '/api/auth/otp/verify' || u === '/api/auth/me') return { prio: 'low', budgetMs: 4000 };
  if (u.startsWith('/admin')) return { prio: 'ui', budgetMs: 30000 };
  return { prio: 'ui' };
}
const server = http.createServer((req, res) => reqContext.run({ device: deviceFromHeader(req), ...shopPrioOf(req) }, () => handleRequest(req, res)));
async function handleRequest(req, res) {
  const url = new URL(req.url, 'http://local');
  const p = url.pathname.replace(/\/+$/, '') || '/';
  try {
    if ((req.method === 'GET' || req.method === 'HEAD') && p === '/health') return send(res, 200, { ok: true });
    if (req.method === 'POST' && p === WEBHOOK_PATH) return await handleWebhook(req, res);
    // Al-Waseet governorates and regions for the website's cart (public, cached).
    if (req.method === 'GET' && p === '/waseet.json') {
      const body = (send.waseet = send.waseet || JSON.stringify(WASEET.map((c) => [c.id, c.name, c.regions])));
      res.writeHead(200, {
        'Content-Type': 'application/json; charset=utf-8',
        'Cache-Control': 'public, max-age=86400',
        'Access-Control-Allow-Origin': '*',
        'X-Content-Type-Options': 'nosniff',
      });
      return res.end(body);
    }

    if (req.method === 'GET' && p === '/update-banner.jpg') {
      res.writeHead(200, { 'Content-Type': 'image/jpeg', 'Cache-Control': 'public, max-age=86400' });
      return res.end(UPDATE_BANNER_JPG);
    }

    if (req.method === 'GET' && (p === '/.well-known/apple-app-site-association' || p === '/apple-app-site-association')) {
      res.writeHead(200, { 'Content-Type': 'application/json', 'Cache-Control': 'public, max-age=3600' });
      return res.end(JSON.stringify(appleAppSiteAssociation()));
    }

    if (req.method === 'GET' && p === '/.well-known/assetlinks.json') {
      res.writeHead(200, { 'Content-Type': 'application/json', 'Cache-Control': 'public, max-age=3600' });
      return res.end(JSON.stringify(assetLinks()));
    }

    {
      const sm = /^\/(p|c)\/([a-z0-9][a-z0-9-]{0,199})$/i.exec(p);
      if (req.method === 'GET' && sm) {
        // Browser (app not installed): the same product on the online store.
        const dest = `${STORE_WEB}/${sm[1] === 'p' ? 'products' : 'collections'}/${sm[2].toLowerCase()}`;
        res.writeHead(302, { Location: dest, 'Cache-Control': 'no-store' });
        return res.end();
      }
    }

    if (req.method === 'GET' && p === '/api/ratings') {
      checkAppKey(req);
      return send(res, 200, await handleRatings());
    }

    if (req.method === 'GET' && p === '/api/reviews') {
      checkAppKey(req);
      return send(res, 200, await handleReviews(String(url.searchParams.get('handle') || '').toLowerCase(), readSession(req)));
    }

    if (req.method === 'POST' && p === '/api/reviews') {
      checkAppKey(req);
      const phone = readSession(req);
      if (!phone) throw new AppError(401, 'سجّل الدخول لتكتب تقييماً');
      rateLimit(phone, 'review', 10, 60 * 60e3);
      let body;
      try {
        body = JSON.parse(await readBody(req, 8192));
      } catch {
        throw new AppError(400, 'طلب غير صالح');
      }
      return send(res, 200, await submitReview(phone, body));
    }

    if (req.method === 'POST' && p === '/api/watch') {
      checkAppKey(req);
      rateLimit(clientIp(req), 'watch', 60, 10 * 60e3);
      let body;
      try {
        body = JSON.parse(await readBody(req, 8192));
      } catch {
        throw new AppError(400, 'طلب غير صالح');
      }
      return send(res, 200, handleWatch(body));
    }

    if (req.method === 'GET' && p === '/api/watch') {
      checkAppKey(req);
      return send(res, 200, listWatches(url.searchParams.get('token')));
    }

    if (req.method === 'GET' && p === '/api/app/status') {
      checkAppKey(req);
      return send(res, 200, appStatus(req));
    }

    if (VERSION_GATED.has(p) || p.startsWith('/api/aqsati/')) checkAppVersion(req);

    if (req.method === 'GET' && p === '/api/config') {
      checkAppKey(req);
      return send(res, 200, await handleConfig());
    }

    if (req.method === 'POST' && p === '/api/orders') {
      checkAppKey(req);
      const raw = await readBody(req);
      let body;
      try {
        body = JSON.parse(raw);
      } catch {
        throw new AppError(400, 'طلب غير صالح');
      }
      return send(res, 200, await handleOrder(body, clientIp(req), readSession(req)));
    }

    if (req.method === 'POST' && (p === '/api/auth/otp/send' || p === '/api/auth/otp/verify')) {
      checkAppKey(req);
      let body;
      try {
        body = JSON.parse(await readBody(req, 4096));
      } catch {
        throw new AppError(400, 'طلب غير صالح');
      }
      const fn = p.endsWith('/send') ? handleOtpSend : handleOtpVerify;
      return send(res, 200, await fn(body, clientIp(req)));
    }

    if (req.method === 'POST' && p === '/api/addons/quote') {
      checkAppKey(req);
      let body;
      try {
        body = JSON.parse(await readBody(req));
      } catch {
        throw new AppError(400, 'طلب غير صالح');
      }
      return send(res, 200, await handleAddonQuote(body));
    }

    if (req.method === 'POST' && p === '/api/discount/check') {
      checkAppKey(req);
      rateLimit(clientIp(req), 'discount', 20, 10 * 60e3);
      let body;
      try {
        body = JSON.parse(await readBody(req));
      } catch {
        throw new AppError(400, 'طلب غير صالح');
      }
      return send(res, 200, await handleDiscountCheck(body, readSession(req)));
    }

    if (req.method === 'POST' && p.startsWith('/api/aqsati/')) {
      checkAppKey(req);
      let body;
      try {
        body = JSON.parse(await readBody(req, p === '/api/aqsati/doc' ? 6 * 1024 * 1024 : undefined));
      } catch (e) {
        if (e instanceof AppError) throw e;
        throw new AppError(400, 'طلب غير صالح');
      }
      const phone = readSession(req);
      const step = p.slice('/api/aqsati/'.length);
      const fn = { start: () => aqsatiStart(body, clientIp(req), phone),
        identity: () => aqsatiIdentity(body, phone),
        plan: () => aqsatiPlan(body, phone),
        doc: () => aqsatiDoc(body, phone),
        confirm: () => aqsatiConfirm(body, phone) }[step];
      if (!fn) throw new AppError(404, 'غير موجود');
      return send(res, 200, await fn());
    }

    if (req.method === 'GET' && p === '/api/auth/me') {
      checkAppKey(req);
      const phone = readSession(req);
      if (!phone) throw new AppError(401, 'انتهت الجلسة، سجّل الدخول مجدداً');
      let profile = null;
      try {
        const c = await customerByPhone(phone);
        if (c) {
          profile = {
            name: [c.firstName, c.lastName].filter(Boolean).join(' ').trim(),
            email: c.defaultEmailAddress?.emailAddress || '',
            orders: Number(c.numberOfOrders || 0),
          };
        }
      } catch (e) {
        log('me profile lookup failed', String(e.message || e).slice(0, 200));
      }
      return send(res, 200, { phone, whatsappConsent: state.consent?.[phone]?.wa === true, profile });
    }

    if (req.method === 'POST' && p === '/api/ai/ask') {
      checkAppKey(req);
      rateLimit(clientIp(req), 'ai', CFG.ai.perIp10min, 10 * 60e3);
      let body;
      try {
        body = JSON.parse(await readBody(req, 16 * 1024));
      } catch {
        throw new AppError(400, 'طلب غير صالح');
      }
      return send(res, 200, await handleAiAsk(body, clientIp(req)));
    }

    if (req.method === 'GET' && p === '/api/orders/mine') {
      checkAppKey(req);
      const phone = readSession(req);
      if (!phone) throw new AppError(401, 'انتهت الجلسة، سجّل الدخول مجدداً');
      rateLimit(phone, 'myorders', 60, 10 * 60e3);
      return send(res, 200, await handleMyOrders(phone));
    }

    if (req.method === 'POST' && (p === '/api/push/register' || p === '/api/push/unregister')) {
      checkAppKey(req);
      rateLimit(clientIp(req), 'push', 30, 10 * 60e3);
      let body;
      try {
        body = JSON.parse(await readBody(req));
      } catch {
        throw new AppError(400, 'طلب غير صالح');
      }
      const token = String(body?.token || '').trim();
      if (token.length < 20 || token.length > 4096) throw new AppError(400, 'طلب غير صالح');
      if (p === '/api/push/unregister') {
        unregisterPushToken(token);
        return send(res, 200, { ok: true });
      }
      const phone = readSession(req);
      if (!phone) throw new AppError(401, 'انتهت الجلسة، سجّل الدخول مجدداً');
      registerPushToken(phone, token, body?.lang);
      return send(res, 200, { ok: true });
    }

    if (req.method === 'GET' && p === '/api/notifications') {
      checkAppKey(req);
      return send(res, 200, withUpdatePromo(req, 'notices', await handleNotices()));
    }

    if (req.method === 'GET' && p === '/api/loyalty/me') {
      checkAppKey(req);
      const phone = readSession(req);
      if (!phone) throw new AppError(401, 'انتهت الجلسة، سجّل الدخول مجدداً');
      rateLimit(phone, 'loyalty', 30, 10 * 60e3);
      return send(res, 200, await handleLoyaltyMe(phone));
    }

    if (req.method === 'POST' && p === '/api/crash') {
      checkAppKey(req);
      rateLimit(clientIp(req), 'crash', 30, 60 * 60e3);
      let body = {};
      try {
        body = JSON.parse(await readBody(req, 16384));
      } catch {}
      return send(res, 200, recordCrash(body));
    }

    if (req.method === 'POST' && p === '/api/cart/rules') {
      checkAppKey(req);
      rateLimit(clientIp(req), 'cart-rules', 120, 10 * 60e3);
      return send(res, 200, await handleCartRules(JSON.parse(await readBody(req, 16384))));
    }

    if (req.method === 'POST' && p === '/api/orders/cancel') {
      checkAppKey(req);
      const phone = readSession(req);
      if (!phone) throw new AppError(401, 'انتهت الجلسة، سجّل الدخول مجدداً');
      rateLimit(phone, 'order-cancel', 6, 60 * 60e3);
      const r = await customerCancelOrder(phone, JSON.parse(await readBody(req, 2048)));
      if (state.myOrdersCache) delete state.myOrdersCache[phone];
      return send(res, 200, r);
    }

    if (req.method === 'POST' && p === '/api/checkout/started') {
      checkAppKey(req);
      const phone = readSession(req);
      if (!phone) return send(res, 200, { ok: true });
      rateLimit(phone, 'checkout-started', 30, 60 * 60e3);
      let body = {};
      try {
        body = JSON.parse(await readBody(req, 2048));
      } catch {}
      return send(res, 200, checkoutStarted(phone, body));
    }

    if (p === '/api/wheel' || p === '/api/wheel/spin') {
      checkAppKey(req);
      const phone = readSession(req);
      if (!phone) throw new AppError(401, 'انتهت الجلسة، سجّل الدخول مجدداً');
      if (req.method === 'GET' && p === '/api/wheel') {
        rateLimit(phone, 'wheel', 40, 10 * 60e3);
        return send(res, 200, await handleWheel(phone));
      }
      if (req.method === 'POST' && p === '/api/wheel/spin') {
        rateLimit(phone, 'wheel-spin', 5, 10 * 60e3);
        return send(res, 200, await spinWheel(phone));
      }
    }

    if (req.method === 'POST' && p === '/api/loyalty/referral') {
      checkAppKey(req);
      const phone = readSession(req);
      if (!phone) throw new AppError(401, 'انتهت الجلسة، سجّل الدخول مجدداً');
      rateLimit(phone, 'referral', 5, 60 * 60e3);
      let body;
      try {
        body = JSON.parse(await readBody(req));
      } catch {
        throw new AppError(400, 'طلب غير صالح');
      }
      return send(res, 200, await handleReferral(phone, body));
    }

    if (req.method === 'GET' && p === '/api/support') {
      checkAppKey(req);
      return send(res, 200, await handleSupport());
    }

    if (req.method === 'GET' && p === '/api/banners') {
      checkAppKey(req);
      return send(res, 200, withUpdatePromo(req, 'banners', await handleBanners()));
    }

    if (req.method === 'POST' && p === '/api/auth/profile') {
      checkAppKey(req);
      const phone = readSession(req);
      if (!phone) throw new AppError(401, 'انتهت الجلسة، سجّل الدخول مجدداً');
      rateLimit(phone, 'profile', 10, 10 * 60e3);
      let body;
      try {
        body = JSON.parse(await readBody(req));
      } catch {
        throw new AppError(400, 'طلب غير صالح');
      }
      return send(res, 200, await handleProfile(phone, body));
    }

    if (req.method === 'POST' && p === '/api/auth/consent') {
      checkAppKey(req);
      const phone = readSession(req);
      if (!phone) throw new AppError(401, 'انتهت الجلسة، سجّل الدخول مجدداً');
      rateLimit(phone, 'consent', 10, 10 * 60e3);
      let body;
      try {
        body = JSON.parse(await readBody(req));
      } catch {
        throw new AppError(400, 'طلب غير صالح');
      }
      if (typeof body?.whatsapp !== 'boolean') throw new AppError(400, 'طلب غير صالح');
      recordConsent(phone, body.whatsapp);
      syncConsent(phone);
      return send(res, 200, { whatsappConsent: body.whatsapp });
    }

    if (p === '/admin' || p.startsWith('/admin/')) {
      if (!(p === '/admin' && req.method === 'POST')) {
        if ((await handleAdmin(req, res, p, url)) !== null) return;
        throw new AppError(404, 'غير موجود');
      }
    }
    if (p === '/admin' && req.method === 'POST') {
      rateLimit(clientIp(req), 'admin', 8, 10 * 60e3);
      const form = new URLSearchParams(await readBody(req, 16 * 1024));
      if (!adminPassOk(form.get('__pass'))) {
        return send(res, 401, adminPage('كلمة المرور غير صحيحة'), 'text/html; charset=utf-8');
      }
      const changes = {};
      for (const [k] of EDITABLE) {
        let v = (form.get(k) || '').trim();
        if (v && k === 'FIREBASE_SERVICE_ACCOUNT' && v !== '-') {
          try {
            const j = JSON.parse(v);
            if (!j.client_email || !j.private_key || !j.project_id) throw new Error('bad');
            v = Buffer.from(JSON.stringify(j)).toString('base64'); // one safe line in .env
          } catch {
            return send(res, 400, adminPage('ملف Firebase غير صحيح: اختر ملف Service account (JSON)'), 'text/html; charset=utf-8');
          }
        }
        if (v) changes[k] = v === '-' ? '' : v;
      }
      if (!Object.keys(changes).length) {
        return send(res, 200, adminPage('لم يتغير شيء', true), 'text/html; charset=utf-8');
      }
      saveEnv(changes);
      log('admin: settings changed', Object.keys(changes).join(','));
      send(res, 200, adminPage('تم الحفظ ✅ الخادم يعيد التشغيل الآن، حدّث الصفحة بعد 5 ثوانٍ.', true), 'text/html; charset=utf-8');
      // systemd (Restart=always) starts it again with the new settings.
      setTimeout(() => process.exit(0), 500);
      return;
    }

    let m;
    if (req.method === 'GET' && (m = p.match(/^\/pay\/([\w-]{20,40})$/))) {
      const pend = state.pending[m[1]];
      if (!pend || pend.status !== 'waiting') {
        return redirect(res, `${CFG.publicUrl}/pay/done?ok=0&msg=${encodeURIComponent('انتهت صلاحية عملية الدفع')}`);
      }
      return send(res, 200, payPage(m[1], pend), 'text/html; charset=utf-8');
    }

    if (req.method === 'GET' && (m = p.match(/^\/pay\/([\w-]{20,40})\/result$/))) {
      rateLimit(clientIp(req), 'pay-result', 30, 10 * 60e3);
      const r = await handlePayResult(m[1]);
      const qs = r.ok
        ? `ok=1&order=${encodeURIComponent(r.orderName)}${r.review ? '&review=1' : ''}`
        : `ok=0&msg=${encodeURIComponent(r.message)}`;
      return redirect(res, `${CFG.publicUrl}/pay/done?${qs}`);
    }

    if (req.method === 'GET' && p === '/pay/done') {
      const ok = url.searchParams.get('ok') === '1';
      const text = ok
        ? `تم الدفع وتسجيل طلبك ${escapeHtml(url.searchParams.get('order') || '')}`
        : escapeHtml(url.searchParams.get('msg') || 'لم يكتمل الدفع');
      return send(
        res,
        200,
        `<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><body style="background:#0A0A0C;color:#F5F5F7;font-family:system-ui;display:grid;place-items:center;height:90vh;text-align:center"><h2>${text}</h2>`,
        'text/html; charset=utf-8'
      );
    }

    send(res, 404, { error: 'غير موجود' });
  } catch (e) {
    const status = e instanceof AppError ? e.status : 500;
    if (status >= 500) log('error', req.method, p, e.stack || e.message);
    send(res, status, { error: e instanceof AppError ? e.message : 'خطأ في الخادم، حاول مرة أخرى' });
  }
}

// -------------------------------------------------------------- webhooks ---
// Shopify tells us the moment an order changes (shipped, Al-Waseet tag,
// delivered, cancelled) instead of us asking every 1–2 minutes. The server
// subscribes its own app ("Ji Fire Order") at start; the pollers stay as a
// safety net. Every call is checked with the app's secret (HMAC).
const WEBHOOK_PATH = '/webhooks/shopify';
const WEBHOOK_TOPICS = ['ORDERS_UPDATED', 'ORDERS_CANCELLED'];
const webhooksOn = () => bool('SHOPIFY_WEBHOOKS', true) && Boolean(CFG.clientSecret) && /^https:\/\//.test(CFG.publicUrl || '');

function webhookValid(raw, hmac) {
  if (!CFG.clientSecret || !hmac) return false;
  const want = crypto.createHmac('sha256', CFG.clientSecret).update(Buffer.from(raw, 'utf8')).digest();
  let got;
  try { got = Buffer.from(String(hmac), 'base64'); } catch { return false; }
  return got.length === want.length && crypto.timingSafeEqual(got, want);
}

// A rush of changes runs the existing checks once, at most every 15 s.
let webhookTimer = null;
let webhookLast = 0;
function webhookKick() {
  if (webhookTimer) return;
  const wait = Math.max(3000, 15000 - (Date.now() - webhookLast));
  webhookTimer = setTimeout(async () => {
    webhookTimer = null;
    webhookLast = Date.now();
    for (const job of [checkFulfilledOrders, checkLoyalty]) {
      try { await job(); } catch (e) { log('webhook job', String(e.message || e).slice(0, 160)); }
    }
  }, wait);
  webhookTimer.unref?.();
}

async function handleWebhook(req, res) {
  const raw = await readBody(req, 2 * 1024 * 1024);
  if (!webhookValid(raw, req.headers['x-shopify-hmac-sha256'])) return send(res, 401, { error: 'bad signature' });
  // Answer at once (Shopify waits 5 s at most), work afterwards.
  send(res, 200, { ok: true });
  state.webhooks = state.webhooks || {};
  state.webhooks.lastAt = new Date().toISOString();
  state.webhooks.count = (state.webhooks.count || 0) + 1;
  try {
    const o = JSON.parse(raw);
    const cid = o?.customer?.id || o?.customer?.admin_graphql_api_id;
    if (cid) {
      const gid = String(cid).startsWith('gid://') ? cid : `gid://shopify/Customer/${cid}`;
      dropMyOrders(gid);
      spendCache.delete(gid);
    }
  } catch {}
  webhookKick();
}

const WEBHOOK_LIST = `
query WebhookList { webhookSubscriptions(first: 50) { nodes { id topic uri } } }`;
const WEBHOOK_CREATE = `
mutation WebhookCreate($topic: WebhookSubscriptionTopic!, $sub: WebhookSubscriptionInput!) {
  webhookSubscriptionCreate(topic: $topic, webhookSubscription: $sub) {
    webhookSubscription { id }
    userErrors { field message }
  }
}`;
const WEBHOOK_DELETE = `
mutation WebhookDelete($id: ID!) { webhookSubscriptionDelete(id: $id) { userErrors { message } } }`;

/** Makes sure our two subscriptions point at this server (and only there). */
async function ensureWebhooks() {
  if (!webhooksOn()) return;
  const uri = CFG.publicUrl.replace(/\/$/, '') + WEBHOOK_PATH;
  try {
    const d = await admin(WEBHOOK_LIST, {}, { prio: 'bg' });
    const subs = d.webhookSubscriptions?.nodes || [];
    for (const s1 of subs) {
      // Ours, but for an old address (e.g. the server's IP changed): remove.
      if (s1.uri && s1.uri.endsWith(WEBHOOK_PATH) && s1.uri !== uri) {
        await admin(WEBHOOK_DELETE, { id: s1.id }, { prio: 'bg', retrySafe: true }).catch(() => {});
      }
    }
    const problems = [];
    for (const topic of WEBHOOK_TOPICS) {
      if (subs.some((x) => x.topic === topic && x.uri === uri)) continue;
      const r = await admin(WEBHOOK_CREATE, { topic, sub: { uri, format: 'JSON', includeFields: ['id', 'updated_at', 'customer'] } }, { prio: 'bg' });
      const errs = r.webhookSubscriptionCreate?.userErrors || [];
      if (errs.length) {
        // Usually: the app lacks "protected customer data" access for orders.
        log('webhook create', topic, JSON.stringify(errs).slice(0, 200));
        problems.push(`${topic}: ${errs.map((e) => e.message).join('; ')}`.slice(0, 160));
      } else log('webhook on', topic);
    }
    state.webhooks = {
      ...(state.webhooks || {}),
      uri,
      ok: problems.length === 0,
      error: problems.length ? problems.join(' | ') : undefined,
      checkedAt: new Date().toISOString(),
    };
    saveState();
  } catch (e) {
    log('webhooks', String(e.message || e).slice(0, 200));
    state.webhooks = { ...(state.webhooks || {}), ok: false, error: String(e.message || e).slice(0, 120) };
  }
}

function redirect(res, location) {
  res.writeHead(302, { Location: location, 'Cache-Control': 'no-store' });
  res.end();
}

if (require.main === module) {
  const missing = [];
  if (!CFG.shop && !CFG.adminBase) missing.push('SHOPIFY_SHOP');
  if (!CFG.staticToken && (!CFG.clientId || !CFG.clientSecret)) {
    missing.push('SHOPIFY_CLIENT_ID / SHOPIFY_CLIENT_SECRET');
  }
  if (!CFG.publicUrl) missing.push('PUBLIC_URL');
  if (missing.length) console.warn('⚠️  Missing settings:', missing.join(', '));
  if (!CFG.appKey) console.warn('⚠️  APP_KEY is empty: anyone can call /api/orders');
  // Only Caddy (on this machine) talks to Node; never reachable from outside.
  // Subscribe to order changes a little after start, then check twice a day.
  setTimeout(() => ensureWebhooks(), 20e3).unref();
  // ID photos: key back from Shopify if the disk was replaced, then copy to S3.
  setTimeout(() => restoreDocsKey().then(() => setTimeout(syncDocsToS3, 30e3)), 1000).unref();
  setInterval(() => syncDocsToS3(), 10 * 60e3).unref();
  setInterval(() => ensureWebhooks(), 12 * 3600e3).unref();
  server.listen(CFG.port, env('HOST', '127.0.0.1'), () => {
    log(`Ji Fire order server on :${CFG.port} | card payments: ${hyperpayEnabled() ? 'on' : 'off'} | OTP login: ${otpEnabled() ? 'on' : 'off'}`);
  });
}

